# Minimal parquet writer for testing
import struct, zlib, gzip, io
class W:
    def __init__(s): s.b=bytearray(); s.stack=[]; s.last=0
    def varint(s,v):
        while True:
            c=v&0x7f; v>>=7
            if v: s.b.append(c|0x80)
            else: s.b.append(c); break
    def zz(s,v): s.varint((v<<1) ^ (v>>63))
    def fh(s,fid,t):
        d=fid-s.last
        if 0<d<=15: s.b.append((d<<4)|t)
        else: s.b.append(t); s.zz(fid)
        s.last=fid
    def i32(s,fid,v): s.fh(fid,5); s.zz(v)
    def i64(s,fid,v): s.fh(fid,6); s.zz(v)
    def bin(s,fid,v):
        if isinstance(v,str): v=v.encode()
        s.fh(fid,8); s.varint(len(v)); s.b+=v
    def boolean(s,fid,v): s.fh(fid,1 if v else 2)
    def begin(s,fid): s.fh(fid,12); s.stack.append(s.last); s.last=0
    def end(s): s.b.append(0); s.last=s.stack.pop()
    def lst(s,fid,et,n):
        s.fh(fid,9)
        if n<15: s.b.append((n<<4)|et)
        else: s.b.append(0xf0|et); s.varint(n)
    def lbegin(s): s.stack.append(s.last); s.last=0
    def stop(s): s.b.append(0)

TYPES={'BOOLEAN':0,'INT32':1,'INT64':2,'INT96':3,'FLOAT':4,'DOUBLE':5,'BYTE_ARRAY':6,'FIXED_LEN_BYTE_ARRAY':7}
REP={'REQUIRED':0,'OPTIONAL':1,'REPEATED':2}

def rle_bitpacked_levels(levels, bw):
    # encode using bit-packed runs (groups of 8)
    out=bytearray()
    if bw==0: return out
    n=len(levels)
    groups=(n+7)//8
    padded=levels+[0]*(groups*8-n)
    out+=bytes()
    hdr=(groups<<1)|1
    # varint
    v=hdr
    while True:
        c=v&0x7f; v>>=7
        if v: out.append(c|0x80)
        else: out.append(c); break
    bits=0; nb=0
    for x in padded:
        bits|=x<<nb; nb+=bw
        while nb>=8: out.append(bits&0xff); bits>>=8; nb-=8
    if nb: out.append(bits&0xff)
    return out

def plain(ptype, vals, tl=None):
    b=bytearray()
    if ptype=='BOOLEAN':
        bits=0;nb=0
        for v in vals:
            bits|=(1 if v else 0)<<nb; nb+=1
            if nb==8: b.append(bits); bits=0; nb=0
        if nb: b.append(bits)
    elif ptype=='INT32':
        for v in vals: b+=struct.pack('<i',v)
    elif ptype=='INT64':
        for v in vals: b+=struct.pack('<q',v)
    elif ptype=='FLOAT':
        for v in vals: b+=struct.pack('<f',v)
    elif ptype=='DOUBLE':
        for v in vals: b+=struct.pack('<d',v)
    elif ptype=='BYTE_ARRAY':
        for v in vals:
            if isinstance(v,str): v=v.encode()
            b+=struct.pack('<i',len(v))+v
    elif ptype in ('FIXED_LEN_BYTE_ARRAY','INT96'):
        for v in vals: b+=v
    return b

class Col:
    def __init__(s, name, ptype, rep='OPTIONAL', converted=None, logical=None, tl=None, scale=None, precision=None):
        s.name=name; s.ptype=ptype; s.rep=rep; s.converted=converted; s.logical=logical; s.tl=tl; s.scale=scale; s.precision=precision

def write_logical(w, fid, lg):
    # lg: ('STRING',) ('INTEGER',bw,signed) ('TIMESTAMP',unit,utc) ('DATE',) ('DECIMAL',scale,prec) ('TIME', unit, utc)
    w.begin(fid)
    k=lg[0]
    if k=='STRING': w.begin(1); w.end()
    elif k=='DATE': w.begin(6); w.end()
    elif k=='INTEGER':
        w.begin(10); w.fh(1,3); w.b.append(lg[1]); w.boolean(2,lg[2]); w.end()
    elif k=='DECIMAL':
        w.begin(5); w.i32(1,lg[1]); w.i32(2,lg[2]); w.end()
    elif k in ('TIMESTAMP','TIME'):
        w.begin(8 if k=='TIMESTAMP' else 7); w.boolean(1,lg[2]); w.begin(2); w.begin({'MILLIS':1,'MICROS':2,'NANOS':3}[lg[1]]); w.end(); w.end(); w.end()
    elif k=='JSON': w.begin(12); w.end()
    elif k=='UUID': w.begin(14); w.end()
    elif k=='FLOAT16': w.begin(15); w.end()
    w.end()

def write_file(path, cols, rowgroups, codec=0, created_by='testwriter', kv=None, stats=True, version=1):
    """rowgroups: list of dict name->list of values (None for null)"""
    out=bytearray(b'PAR1')
    rg_meta=[]
    for rg in rowgroups:
        nrows=len(rg[cols[0].name])
        chunks=[]
        rg_start=len(out)
        for c in cols:
            vals=rg[c.name]
            nn=[v for v in vals if v is not None]
            body=bytearray()
            if c.rep=='OPTIONAL':
                lv=rle_bitpacked_levels([0 if v is None else 1 for v in vals],1)
                body+=struct.pack('<i',len(lv))+lv
            body+=plain(c.ptype, nn)
            unc=bytes(body)
            if codec==2:
                comp=gzip.compress(unc, mtime=0)
            else: comp=unc
            ph=W()
            ph.i32(1,0); ph.i32(2,len(unc)); ph.i32(3,len(comp))
            ph.begin(5); ph.i32(1,len(vals)); ph.i32(2,0); ph.i32(3,3); ph.i32(4,3); ph.end()
            ph.stop()
            off=len(out)
            out+=ph.b+comp
            chunks.append(dict(off=off, unc=len(ph.b)+len(unc), comp=len(ph.b)+len(comp), nvals=len(vals), col=c, nn=nn, nulls=len(vals)-len(nn)))
        rg_meta.append((nrows, chunks, rg_start))
    # footer
    w=W()
    w.i32(1,version)
    # schema
    w.lst(2,12,len(cols)+1)
    w.lbegin(); w.bin(4,'schema'); w.i32(5,len(cols)); w.stop(); w.last=w.stack.pop()
    for c in cols:
        w.lbegin()
        w.i32(1,TYPES[c.ptype])
        if c.tl: w.i32(2,c.tl)
        w.i32(3,REP[c.rep]); w.bin(4,c.name)
        if c.converted is not None: w.i32(6,c.converted)
        if c.scale is not None: w.i32(7,c.scale)
        if c.precision is not None: w.i32(8,c.precision)
        if c.logical: write_logical(w,10,c.logical)
        w.stop(); w.last=w.stack.pop()
    total_rows=sum(r[0] for r in rg_meta)
    w.i64(3,total_rows)
    w.lst(4,12,len(rg_meta))
    for nrows,chunks,rg_start in rg_meta:
        w.lbegin()
        w.lst(1,12,len(chunks))
        for ch in chunks:
            w.lbegin()
            w.i64(2,ch['off'])
            w.begin(3)
            c=ch['col']
            w.i32(1,TYPES[c.ptype])
            w.lst(2,5,2); w.zz(0); w.zz(3)
            w.lst(3,8,1); w.varint(len(c.name)); w.b+=c.name.encode()
            w.i32(4,codec)
            w.i64(5,ch['nvals']); w.i64(6,ch['unc']); w.i64(7,ch['comp'])
            w.i64(9,ch['off'])
            if stats and c.ptype in ('INT32','INT64','BYTE_ARRAY','DOUBLE'):
                nn=ch['nn']
                w.begin(12)
                w.i64(3,ch['nulls'])
                if nn:
                    mn=plain(c.ptype,[min(nn)]); mx=plain(c.ptype,[max(nn)])
                    if c.ptype=='BYTE_ARRAY': mn=mn[4:]; mx=mx[4:]
                    w.bin(5,bytes(mx)); w.bin(6,bytes(mn))
                w.end()
            w.end()
            w.stop(); w.last=w.stack.pop()
        w.i64(2,sum(c['unc'] for c in chunks)); w.i64(3,nrows)
        w.stop(); w.last=w.stack.pop()
    if kv:
        w.lst(5,12,len(kv))
        for k,v in kv:
            w.lbegin(); w.bin(1,k)
            if v is not None: w.bin(2,v)
            w.stop(); w.last=w.stack.pop()
    if created_by is not None: w.bin(6,created_by)
    w.stop()
    out+=w.b+struct.pack('<i',len(w.b))+b'PAR1'
    open(path,'wb').write(out)
