pub struct Reader<'a> {
    pub buf: &'a [u8],
    pub pos: usize,
    depth: usize,
}

pub type TResult<T> = Result<T, String>;

const EOF_MSG: &str = "Unexpected EOF";

impl<'a> Reader<'a> {
    pub fn new(buf: &'a [u8]) -> Self {
        Reader { buf, pos: 0, depth: 0 }
    }

    fn byte(&mut self) -> TResult<u8> {
        if self.pos >= self.buf.len() {
            return Err(EOF_MSG.to_string());
        }
        let b = self.buf[self.pos];
        self.pos += 1;
        Ok(b)
    }

    pub fn varint(&mut self) -> TResult<u64> {
        let mut result: u64 = 0;
        let mut shift = 0u32;
        loop {
            let b = self.byte()?;
            if shift < 64 {
                result |= ((b & 0x7f) as u64) << shift;
            }
            if b & 0x80 == 0 {
                return Ok(result);
            }
            shift += 7;
            if shift > 70 {
                return Err("Invalid varint".to_string());
            }
        }
    }

    pub fn zigzag(&mut self) -> TResult<i64> {
        let v = self.varint()?;
        Ok(((v >> 1) as i64) ^ (-((v & 1) as i64)))
    }

    fn binary(&mut self) -> TResult<Vec<u8>> {
        let n = self.varint()? as usize;
        if self.pos + n > self.buf.len() || n > self.buf.len() {
            return Err(EOF_MSG.to_string());
        }
        let v = self.buf[self.pos..self.pos + n].to_vec();
        self.pos += n;
        Ok(v)
    }

    fn value(&mut self, t: u8) -> TResult<TVal> {
        Ok(match t {
            1 => TVal::Bool(true),
            2 => TVal::Bool(false),
            3 => TVal::I8(self.byte()? as i8),
            4 => TVal::I16(self.zigzag()? as i16),
            5 => TVal::I32(self.zigzag()? as i32),
            6 => TVal::I64(self.zigzag()?),
            7 => {
                if self.pos + 8 > self.buf.len() {
                    return Err(EOF_MSG.to_string());
                }
                let mut a = [0u8; 8];
                a.copy_from_slice(&self.buf[self.pos..self.pos + 8]);
                self.pos += 8;
                TVal::Double(f64::from_le_bytes(a))
            }
            8 => TVal::Binary(self.binary()?),
            9 | 10 => {
                let h = self.byte()?;
                let mut n = (h >> 4) as usize;
                let et = h & 0x0f;
                if n == 15 {
                    n = self.varint()? as usize;
                }
                if n > self.buf.len() {
                    return Err(EOF_MSG.to_string());
                }
                let mut v = Vec::with_capacity(n);
                for _ in 0..n {
                    if et == 1 || et == 2 {
                        let b = self.byte()?;
                        v.push(TVal::Bool(b == 1));
                    } else {
                        v.push(self.value(et)?);
                    }
                }
                TVal::List(v)
            }
            11 => {
                let n = self.varint()? as usize;
                if n == 0 {
                    return Ok(TVal::Map(vec![]));
                }
                if n > self.buf.len() {
                    return Err(EOF_MSG.to_string());
                }
                let kv = self.byte()?;
                let mut v = Vec::with_capacity(n);
                for _ in 0..n {
                    let k = self.value(kv >> 4)?;
                    let val = self.value(kv & 0x0f)?;
                    v.push((k, val));
                }
                TVal::Map(v)
            }
            12 => TVal::Struct(self.read_struct()?),
            _ => return Err(format!("Invalid thrift type {}", t)),
        })
    }

    pub fn read_struct(&mut self) -> TResult<TStruct> {
        self.depth += 1;
        if self.depth > 64 {
            return Err("Thrift nesting too deep".to_string());
        }
        let mut s = TStruct::default();
        let mut last: i16 = 0;
        loop {
            let h = self.byte()?;
            if h == 0 {
                break;
            }
            let t = h & 0x0f;
            let delta = (h >> 4) as i16;
            let fid = if delta != 0 {
                last.wrapping_add(delta)
            } else {
                self.zigzag()? as i16
            };
            last = fid;
            let v = self.value(t)?;
            s.fields.push((fid, v));
        }
        self.depth -= 1;
        Ok(s)
    }
}
