pub fn encoding_name(e: i32) -> String {
    match e {
        0 => "PLAIN".into(),
        1 => "GROUP_VAR_INT".into(),
        2 => "PLAIN_DICTIONARY".into(),
        3 => "RLE".into(),
        4 => "BIT_PACKED".into(),
        5 => "DELTA_BINARY_PACKED".into(),
        6 => "DELTA_LENGTH_BYTE_ARRAY".into(),
        7 => "DELTA_BYTE_ARRAY".into(),
        8 => "RLE_DICTIONARY".into(),
        9 => "BYTE_STREAM_SPLIT".into(),
        _ => format!("UNKNOWN({})", e),
    }
}

pub fn codec_name(c: i32) -> String {
    match c {
        0 => "UNCOMPRESSED".into(),
        1 => "SNAPPY".into(),
        2 => "GZIP(GzipLevel(6))".into(),
        3 => "LZO".into(),
        4 => "BROTLI(BrotliLevel(1))".into(),
        5 => "LZ4".into(),
        6 => "ZSTD(ZstdLevel(1))".into(),
        7 => "LZ4_RAW".into(),
        _ => format!("UNKNOWN({})", c),
    }
}

fn bin(v: Option<&[u8]>) -> Option<Vec<u8>> {
    v.map(|b| b.to_vec())
}

fn parse_stats(s: &TStruct) -> Statistics {
    Statistics {
        max: bin(s.bin(1)),
        min: bin(s.bin(2)),
        null_count: s.i64(3),
        distinct_count: s.i64(4),
        max_value: bin(s.bin(5)),
        min_value: bin(s.bin(6)),
    }
}

fn time_unit(s: &TStruct) -> TimeUnit {
    if s.get(1).is_some() {
        TimeUnit::Millis
    } else if s.get(2).is_some() {
        TimeUnit::Micros
    } else {
        TimeUnit::Nanos
    }
}

fn parse_logical(s: &TStruct) -> Option<LogicalType> {
    let (id, v) = s.fields.first()?;
    let inner = v.as_struct();
    Some(match id {
        1 => LogicalType::String,
        2 => LogicalType::Map,
        3 => LogicalType::List,
        4 => LogicalType::Enum,
        5 => {
            let i = inner?;
            LogicalType::Decimal { scale: i.i32(1).unwrap_or(0), precision: i.i32(2).unwrap_or(0) }
        }
        6 => LogicalType::Date,
        7 => {
            let i = inner?;
            LogicalType::Time {
                utc: i.bool(1).unwrap_or(false),
                unit: i.strukt(2).map(time_unit).unwrap_or(TimeUnit::Millis),
            }
        }
        8 => {
            let i = inner?;
            LogicalType::Timestamp {
                utc: i.bool(1).unwrap_or(false),
                unit: i.strukt(2).map(time_unit).unwrap_or(TimeUnit::Millis),
            }
        }
        10 => {
            let i = inner?;
            LogicalType::Integer { bits: i.i32(1).unwrap_or(32) as i8, signed: i.bool(2).unwrap_or(true) }
        }
        11 => LogicalType::Unknown,
        12 => LogicalType::Json,
        13 => LogicalType::Bson,
        14 => LogicalType::Uuid,
        15 => LogicalType::Float16,
        _ => LogicalType::Other,
    })
}

fn parse_schema_element(s: &TStruct) -> Result<SchemaElement, String> {
    let ptype = match s.i32(1) {
        Some(v) => Some(PhysType::from_i32(v)?),
        None => None,
    };
    let repetition = match s.i32(3) {
        Some(0) => Some(Repetition::Required),
        Some(1) => Some(Repetition::Optional),
        Some(2) => Some(Repetition::Repeated),
        Some(v) => return Err(format!("unexpected parquet repetition type: {}", v)),
        None => None,
    };
    Ok(SchemaElement {
        ptype,
        type_length: s.i32(2),
        repetition,
        name: s.string(4).unwrap_or_default(),
        num_children: s.i32(5),
        converted: s.i32(6),
        scale: s.i32(7),
        precision: s.i32(8),
        field_id: s.i32(9),
        logical: s.strukt(10).and_then(parse_logical),
    })
}

fn parse_column_meta(s: &TStruct) -> Result<ColumnMeta, String> {
    let ptype = PhysType::from_i32(s.i32(1).ok_or("protocol error")?)?;
    let encodings = s
        .list(2)
        .map(|l| l.iter().filter_map(|v| v.as_i64()).map(|v| v as i32).collect())
        .unwrap_or_default();
    let path = s
        .list(3)
        .map(|l| {
            l.iter()
                .filter_map(|v| match v {
                    TVal::Binary(b) => Some(String::from_utf8_lossy(b).into_owned()),
                    _ => None,
                })
                .collect()
        })
        .unwrap_or_default();
    let encoding_stats = s.list(13).map(|l| {
        l.iter()
            .filter_map(|v| v.as_struct())
            .map(|e| PageEncodingStats {
                page_type: e.i32(1).unwrap_or(0),
                encoding: e.i32(2).unwrap_or(0),
                count: e.i32(3).unwrap_or(0),
            })
            .collect()
    });
    Ok(ColumnMeta {
        ptype,
        encodings,
        path,
        codec: s.i32(4).unwrap_or(0),
        num_values: s.i64(5).unwrap_or(0),
        total_uncompressed_size: s.i64(6).unwrap_or(0),
        total_compressed_size: s.i64(7).unwrap_or(0),
        data_page_offset: s.i64(9).unwrap_or(0),
        index_page_offset: s.i64(10),
        dictionary_page_offset: s.i64(11),
        statistics: s.strukt(12).map(parse_stats),
        encoding_stats,
        bloom_filter_offset: s.i64(14),
        bloom_filter_length: s.i32(15),
    })
}

pub fn parse_file_meta(buf: &[u8]) -> Result<FileMeta, String> {
    let mut r = Reader::new(buf);
    let s = r.read_struct().map_err(|e| {
        if e.contains("EOF") {
            "Could not parse metadata: end of file".to_string()
        } else {
            "Could not parse metadata: protocol error".to_string()
        }
    })?;
    let proto = || "Could not parse metadata: protocol error".to_string();
    let version = s.i32(1).ok_or_else(proto)?;
    let schema_list = s.list(2).ok_or_else(proto)?;
    let num_rows = s.i64(3).ok_or_else(proto)?;
    let rg_list = s.list(4).ok_or_else(proto)?;
    let mut schema = Vec::new();
    for e in schema_list {
        let st = e.as_struct().ok_or_else(proto)?;
        schema.push(parse_schema_element(st)?);
    }
    let mut row_groups = Vec::new();
    for rg in rg_list {
        let rs = rg.as_struct().ok_or_else(proto)?;
        let mut columns = Vec::new();
        for c in rs.list(1).unwrap_or(&[]) {
            let cs = c.as_struct().ok_or_else(proto)?;
            let meta = match cs.strukt(3) {
                Some(m) => Some(parse_column_meta(m)?),
                None => None,
            };
            columns.push(ColumnChunk {
                file_offset: cs.i64(2).unwrap_or(0),
                meta,
                offset_index_offset: cs.i64(4),
                offset_index_length: cs.i32(5),
                column_index_offset: cs.i64(6),
                column_index_length: cs.i32(7),
            });
        }
        row_groups.push(RowGroup {
            columns,
            total_byte_size: rs.i64(2).unwrap_or(0),
            num_rows: rs.i64(3).unwrap_or(0),
            file_offset: rs.i64(5),
            total_compressed_size: rs.i64(6),
            ordinal: rs.i64(7).map(|v| v as i16),
        });
    }
    let key_value = s
        .list(5)
        .map(|l| {
            l.iter()
                .filter_map(|v| v.as_struct())
                .map(|kv| (kv.string(1).unwrap_or_default(), kv.string(2)))
                .collect()
        })
        .unwrap_or_default();
    Ok(FileMeta { version, schema, num_rows, row_groups, key_value, created_by: s.string(6) })
}

pub fn parse_page_header(buf: &[u8]) -> Result<(PageHeader, usize), String> {
    let mut r = Reader::new(buf);
    let s = r.read_struct()?;
    let data = s.strukt(5).map(|d| DataPageHeader {
        num_values: d.i32(1).unwrap_or(0),
        encoding: d.i32(2).unwrap_or(0),
        def_encoding: d.i32(3).unwrap_or(3),
        rep_encoding: d.i32(4).unwrap_or(3),
        statistics: d.strukt(5).map(parse_stats),
    });
    let dict = s.strukt(7).map(|d| DictPageHeader {
        num_values: d.i32(1).unwrap_or(0),
        encoding: d.i32(2).unwrap_or(0),
        is_sorted: d.bool(3),
    });
    let data_v2 = s.strukt(8).map(|d| DataPageHeaderV2 {
        num_values: d.i32(1).unwrap_or(0),
        num_nulls: d.i32(2).unwrap_or(0),
        num_rows: d.i32(3).unwrap_or(0),
        encoding: d.i32(4).unwrap_or(0),
        def_len: d.i32(5).unwrap_or(0),
        rep_len: d.i32(6).unwrap_or(0),
        is_compressed: d.bool(7).unwrap_or(true),
        statistics: d.strukt(8).map(parse_stats),
    });
    Ok((
        PageHeader {
            page_type: s.i32(1).unwrap_or(-1),
            uncompressed_size: s.i32(2).unwrap_or(0),
            compressed_size: s.i32(3).unwrap_or(0),
            crc: s.i32(4),
            data,
            dict,
            data_v2,
        },
        r.pos,
    ))
}
