/// Decompress a raw LZ4 block into `out` (appending). Returns number of bytes produced.
pub fn lz4_block(src: &[u8], out: &mut Vec<u8>, max_out: usize) -> Result<(), String> {
    let base = out.len();
    let mut pos = 0usize;
    let err = || "lz4: corrupt input".to_string();
    loop {
        if pos >= src.len() {
            return Err(err());
        }
        let token = src[pos];
        pos += 1;
        let mut lit = (token >> 4) as usize;
        if lit == 15 {
            loop {
                if pos >= src.len() {
                    return Err(err());
                }
                let b = src[pos];
                pos += 1;
                lit += b as usize;
                if b != 255 {
                    break;
                }
            }
        }
        if pos + lit > src.len() {
            return Err(err());
        }
        out.extend_from_slice(&src[pos..pos + lit]);
        pos += lit;
        if out.len() - base > max_out {
            return Err(err());
        }
        if pos == src.len() {
            return Ok(());
        }
        if pos + 2 > src.len() {
            return Err(err());
        }
        let off = src[pos] as usize | ((src[pos + 1] as usize) << 8);
        pos += 2;
        let mut ml = (token & 15) as usize;
        if ml == 15 {
            loop {
                if pos >= src.len() {
                    return Err(err());
                }
                let b = src[pos];
                pos += 1;
                ml += b as usize;
                if b != 255 {
                    break;
                }
            }
        }
        ml += 4;
        if off == 0 || off > out.len() - base {
            return Err(err());
        }
        let start = out.len() - off;
        for i in 0..ml {
            let b = out[start + i];
            out.push(b);
        }
        if out.len() - base > max_out {
            return Err(err());
        }
    }
}

fn lz4_hadoop(src: &[u8], expected: usize) -> Result<Vec<u8>, String> {
    let mut out = Vec::with_capacity(expected);
    let mut pos = 0usize;
    let err = || "lz4 hadoop: corrupt".to_string();
    while pos < src.len() {
        if pos + 8 > src.len() {
            return Err(err());
        }
        let ulen = u32::from_be_bytes([src[pos], src[pos + 1], src[pos + 2], src[pos + 3]]) as usize;
        let clen = u32::from_be_bytes([src[pos + 4], src[pos + 5], src[pos + 6], src[pos + 7]]) as usize;
