            return Err(err());
        }
        pos += clen;
    }
    if out.len() != expected {
        return Err(err());
    }
    Ok(out)
}

fn lz4_frame(src: &[u8], expected: usize) -> Result<Vec<u8>, String> {
    let err = || "lz4 frame: corrupt".to_string();
    if src.len() < 7 || src[0..4] != [0x04, 0x22, 0x4d, 0x18] {
        return Err(err());
    }
    let flg = src[4];
    let mut pos = 6;
    if flg & 0x08 != 0 {
        pos += 8;
    }
    if flg & 0x01 != 0 {
        pos += 4;
    }
    pos += 1; // header checksum
    let block_checksum = flg & 0x10 != 0;
    let mut out = Vec::with_capacity(expected);
    loop {
        if pos + 4 > src.len() {
            return Err(err());
        }
        let bs = u32::from_le_bytes([src[pos], src[pos + 1], src[pos + 2], src[pos + 3]]);
        pos += 4;
