        if uncompressed {
            out.extend_from_slice(&src[pos..pos + len]);
        } else {
            lz4_block(&src[pos..pos + len], &mut out, usize::MAX / 2)?;
        }
        pos += len;
        if block_checksum {
            pos += 4;
        }
    }
    Ok(out)
}

pub fn decompress(codec: i32, src: &[u8], uncompressed_size: usize) -> Result<Vec<u8>, String> {
    match codec {
        0 => Ok(src.to_vec()),
        1 => snappy_decompress(src),
        2 => {
            let mut d = flate2::read::MultiGzDecoder::new(src);
            let mut out = Vec::with_capacity(uncompressed_size);
            d.read_to_end(&mut out).map_err(|e| e.to_string())?;
            Ok(out)
        }
        5 => {
            if let Ok(v) = lz4_hadoop(src, uncompressed_size) {
                return Ok(v);
            }
            let mut out = Vec::with_capacity(uncompressed_size);
            if lz4_block(src, &mut out, uncompressed_size).is_ok() && out.len() == uncompressed_size {
                return Ok(out);
            }
            lz4_frame(src, uncompressed_size)
        }
        7 => {
            let mut out = Vec::with_capacity(uncompressed_size);
            lz4_block(src, &mut out, uncompressed_size)?;
            Ok(out)
        }
        6 => super::zstd::decompress(src),
        4 => Err("brotli compression is not supported".into()),
        3 => Err("lzo compression is not supported".into()),
        _ => Err(format!("unknown compression codec {}", codec)),
    }
}
