//! A straightforward Zstandard (RFC 8878) decoder.

type R<T> = Result<T, String>;

fn err<T>(m: &str) -> R<T> {
    Err(format!("zstd: {}", m))
}

/// Forward little-endian bit reader (used for FSE table descriptions).
struct FwdBits<'a> {
    buf: &'a [u8],
    pos: usize, // bit position
}

impl<'a> FwdBits<'a> {
    fn peek(&self, n: u32) -> u32 {
        let mut v: u64 = 0;
        let byte = self.pos / 8;
        for i in 0..8 {
            let b = if byte + i < self.buf.len() { self.buf[byte + i] } else { 0 };
            v |= (b as u64) << (8 * i);
        }
        let v = v >> (self.pos % 8);
        if n == 0 {
            0
        } else {
            (v & ((1u64 << n) - 1)) as u32
        }
    }
    fn skip(&mut self, n: u32) {
        self.pos += n as usize;
    }
    fn read(&mut self, n: u32) -> u32 {
        let v = self.peek(n);
        self.skip(n);
        v
    }
}

/// Backward bit reader as used by zstd bitstreams.
struct BackBits<'a> {
    buf: &'a [u8],
    pos: i64, // number of bits still available (bits below this index)
}

impl<'a> BackBits<'a> {
    fn new(buf: &'a [u8]) -> R<Self> {
        if buf.is_empty() {
            return err("empty bitstream");
        }
        let last = buf[buf.len() - 1];
        if last == 0 {
            return err("bitstream missing end marker");
        }
        let hb = 7 - last.leading_zeros() as i64; // index of highest set bit
        let pos = (buf.len() as i64 - 1) * 8 + hb;
        Ok(BackBits { buf, pos })
    }
    fn bit(&self, i: i64) -> u64 {
        if i < 0 {
            return 0;
        }
        let byte = (i / 8) as usize;
        ((self.buf[byte] >> (i % 8)) & 1) as u64
    }
    fn peek(&self, n: u32) -> u64 {
        if n == 0 {
            return 0;
        }
        let start = self.pos - n as i64;
        // fast path
        if start >= 0 {
            let sb = (start / 8) as usize;
            let mut v: u64 = 0;
            let mut cnt = 0;
            let mut i = sb;
            while i < self.buf.len() && cnt < 8 {
                v |= (self.buf[i] as u64) << (8 * cnt);
                cnt += 1;
                i += 1;
            }
            let v = v >> (start % 8);
            if n >= 57 {
                // fallback slow
                let mut r = 0u64;
                for k in 0..n as i64 {
                    r |= self.bit(start + k) << k;
                }
                return r;
            }
            return v & ((1u64 << n) - 1);
        }
        let mut r = 0u64;
        for k in 0..n as i64 {
            r |= self.bit(start + k) << k;
        }
        r
    }
    fn read(&mut self, n: u32) -> u64 {
        let v = self.peek(n);
        self.pos -= n as i64;
        v
    }
    fn overflowed(&self) -> bool {
        self.pos < 0
    }
}

#[derive(Clone, Copy, Default)]
struct FseEntry {
    symbol: u16,
    nb_bits: u8,
    baseline: u16,
}

#[derive(Clone, Default)]
struct FseTable {
    log: u32,
    entries: Vec<FseEntry>,
}

fn build_fse(norm: &[i16], log: u32) -> R<FseTable> {
    let size = 1usize << log;
    let mut entries = vec![FseEntry::default(); size];
    let mut high = size as i64 - 1;
    let mut next = vec![0u32; norm.len()];
    for (s, &c) in norm.iter().enumerate() {
        if c == -1 {
            if high < 0 {
                return err("bad fse table");
            }
            entries[high as usize].symbol = s as u16;
            high -= 1;
            next[s] = 1;
        } else {
            next[s] = c.max(0) as u32;
        }
    }
    let step = (size >> 1) + (size >> 3) + 3;
    let mask = size - 1;
    let mut pos = 0usize;
    for (s, &c) in norm.iter().enumerate() {
        if c <= 0 {
            continue;
        }
        for _ in 0..c {
            entries[pos].symbol = s as u16;
            loop {
                pos = (pos + step) & mask;
                if (pos as i64) <= high {
                    break;
                }
            }
        }
    }
    if pos != 0 {
        return err("bad fse spread");
    }
    for e in entries.iter_mut() {
        let s = e.symbol as usize;
        let ns = next[s];
        next[s] += 1;
        if ns == 0 {
            return err("bad fse state");
        }
        let hb = 31 - ns.leading_zeros();
        let nb = log - hb;
        e.nb_bits = nb as u8;
        e.baseline = ((ns << nb) as i64 - size as i64) as u16;
    }
    Ok(FseTable { log, entries })
}

/// Read an FSE table description. Returns table and bytes consumed.
fn read_fse_desc(buf: &[u8], max_symbol: usize, max_log: u32) -> R<(FseTable, usize)> {
    let mut br = FwdBits { buf, pos: 0 };
    let log = br.read(4) + 5;
    if log > max_log {
        return err("fse table log too large");
    }
    let mut remaining: i32 = (1 << log) + 1;
    let mut threshold: i32 = 1 << log;
    let mut nb_bits: u32 = log + 1;
    let mut norm: Vec<i16> = Vec::new();
    let mut prev0 = false;
    while remaining > 1 && norm.len() <= max_symbol {
        if prev0 {
            loop {
                let n = br.read(2);
                for _ in 0..n {
                    norm.push(0);
                }
                if n != 3 {
                    break;
                }
            }
            if norm.len() > max_symbol {
                break;
            }
        }
        let max = (2 * threshold - 1) - remaining;
        let low = br.peek(nb_bits - 1) as i32;
        let mut count;
        if low < max {
            count = low;
            br.skip(nb_bits - 1);
        } else {
            count = br.peek(nb_bits) as i32;
            if count >= threshold {
                count -= max;
            }
            br.skip(nb_bits);
        }
        count -= 1;
        remaining -= count.abs();
        norm.push(count as i16);
        prev0 = count == 0;
        while remaining < threshold && nb_bits > 1 {
            nb_bits -= 1;
            threshold >>= 1;
        }
    }
    if remaining != 1 || norm.len() > max_symbol + 1 {
        return err("bad fse description");
    }
    let consumed = (br.pos + 7) / 8;
    if consumed > buf.len() {
        return err("fse description truncated");
    }
    Ok((build_fse(&norm, log)?, consumed))
}

fn rle_table(sym: u16) -> FseTable {
    FseTable { log: 0, entries: vec![FseEntry { symbol: sym, nb_bits: 0, baseline: 0 }] }
}

const LL_DEFAULT: [i16; 36] = [
