        }
        let b = buf[*pos];
        *pos += 1;
        if shift < 64 {
            r |= ((b & 0x7f) as u64) << shift;
        }
        if b & 0x80 == 0 {
            return Ok(r);
        }
        shift += 7;
        if shift > 70 {
            return Err("bad varint".into());
        }
    }
}

fn zigzag_varint(buf: &[u8], pos: &mut usize) -> R<i64> {
    let v = ulong_varint(buf, pos)?;
    Ok(((v >> 1) as i64) ^ (-((v & 1) as i64)))
}

/// Read `count` values of `bw` bits each, LSB-first bit packing.
pub fn unpack_bits(buf: &[u8], start_bit: usize, bw: u32, count: usize, out: &mut Vec<u64>) {
    if bw == 0 {
        out.extend(std::iter::repeat(0).take(count));
        return;
    }
    let mut bitpos = start_bit;
    for _ in 0..count {
        let mut v: u64 = 0;
        let mut got = 0u32;
        while got < bw {
            let byte = bitpos / 8;
            let off = (bitpos % 8) as u32;
            let b = if byte < buf.len() { buf[byte] as u64 } else { 0 };
            let take = (8 - off).min(bw - got);
            let bits = (b >> off) & ((1u64 << take) - 1);
            v |= bits << got;
            got += take;
            bitpos += take as usize;
        }
        out.push(v);
    }
}

/// Decode an RLE/bit-packed hybrid stream producing up to `count` values.
pub fn rle_hybrid(buf: &[u8], bw: u32, count: usize) -> R<Vec<u64>> {
    let mut out: Vec<u64> = Vec::with_capacity(count);
    let mut pos = 0usize;
    let vbytes = ((bw + 7) / 8) as usize;
    while out.len() < count {
        if pos >= buf.len() {
            break;
        }
        let h = ulong_varint(buf, &mut pos)?;
        if h & 1 == 1 {
            let groups = (h >> 1) as usize;
            let n = groups * 8;
            let nbytes = groups * bw as usize;
            let take = n.min(count - out.len());
            unpack_bits(&buf[pos..buf.len().min(pos + nbytes)], 0, bw, take, &mut out);
            pos += nbytes;
        } else {
            let n = (h >> 1) as usize;
            let mut v: u64 = 0;
            for i in 0..vbytes {
                let b = if pos + i < buf.len() { buf[pos + i] } else { 0 };
                v |= (b as u64) << (8 * i);
            }
            pos += vbytes;
            let take = n.min(count - out.len());
            out.extend(std::iter::repeat(v).take(take));
        }
    }
    while out.len() < count {
        out.push(0);
    }
    Ok(out)
}

/// Legacy BIT_PACKED (MSB-first) level encoding.
pub fn bit_packed_legacy(buf: &[u8], bw: u32, count: usize) -> Vec<u64> {
    let mut out = Vec::with_capacity(count);
    let mut bitpos = 0usize;
    for _ in 0..count {
        let mut v = 0u64;
        for _ in 0..bw {
            let byte = bitpos / 8;
            let b = if byte < buf.len() { buf[byte] } else { 0 };
            let bit = (b >> (7 - (bitpos % 8))) & 1;
            v = (v << 1) | bit as u64;
            bitpos += 1;
        }
        out.push(v);
    }
    out
}

/// DELTA_BINARY_PACKED decoding. Returns values and bytes consumed.
pub fn delta_binary_packed(buf: &[u8], max_values: usize) -> R<(Vec<i64>, usize)> {
    let mut pos = 0usize;
    let block_size = ulong_varint(buf, &mut pos)? as usize;
    let miniblocks = ulong_varint(buf, &mut pos)? as usize;
    let total = ulong_varint(buf, &mut pos)? as usize;
    let first = zigzag_varint(buf, &mut pos)?;
    if miniblocks == 0 || block_size % miniblocks != 0 {
        return Err("invalid delta header".into());
    }
    let per_mini = block_size / miniblocks;
    let mut out: Vec<i64> = Vec::with_capacity(total.min(max_values.max(1)));
    if total == 0 {
        return Ok((out, pos));
    }
    out.push(first);
    let mut last = first;
    while out.len() < total {
        let min_delta = zigzag_varint(buf, &mut pos)?;
        if pos + miniblocks > buf.len() {
            return Err("delta: truncated bit widths".into());
        }
        let widths: Vec<u32> = buf[pos..pos + miniblocks].iter().map(|&b| b as u32).collect();
        pos += miniblocks;
        for &bw in widths.iter() {
            if out.len() >= total {
                break;
            }
            let nbytes = per_mini * bw as usize / 8;
            let mut vals = Vec::with_capacity(per_mini);
            let end = (pos + nbytes).min(buf.len());
            unpack_bits(&buf[pos..end], 0, bw, per_mini, &mut vals);
            pos += nbytes;
            for v in vals {
                if out.len() >= total {
                    break;
                }
                last = last.wrapping_add(min_delta).wrapping_add(v as i64);
                out.push(last);
            }
        }
    }
    Ok((out, pos.min(buf.len())))
}
