//! Reading column chunk pages into levels + values.
use super::compress;
use super::encoding::*;
use super::meta::*;

type R<T> = Result<T, String>;

#[derive(Debug, Clone)]
pub enum PVal {
    Bool(bool),
    I32(i32),
    I64(i64),
    I96([u8; 12]),
    F32(f32),
    F64(f64),
    Bytes(Vec<u8>),
}

#[derive(Debug, Clone)]
pub struct PageInfo {
    pub page_type: i32,
    pub compressed_size: i32,
    pub uncompressed_size: i32,
    pub num_values: Option<i32>,
    pub num_rows: Option<i32>,
    pub encoding: Option<i32>,
    pub header_size: usize,
}

pub struct ColumnData {
    pub def: Vec<u16>,
    pub rep: Vec<u16>,
    pub values: Vec<PVal>,
}

pub fn spec_err(msg: &str) -> String {
    format!("parquet: File out of specification: {}", msg)
}

fn bit_width(max: u16) -> u32 {
    if max == 0 {
        0
    } else {
        16 - max.leading_zeros()
    }
}

fn chunk_range(cm: &ColumnMeta) -> (i64, i64) {
    let mut start = cm.data_page_offset;
    if let Some(d) = cm.dictionary_page_offset {
        if d > 0 && d < start {
            start = d;
        }
    }
    (start, cm.total_compressed_size)
}

/// List page headers of a column chunk (for display).
pub fn list_pages(file: &[u8], cm: &ColumnMeta) -> Vec<PageInfo> {
    let (start, len) = chunk_range(cm);
    let mut out = Vec::new();
    if start < 0 || len < 0 {
        return out;
    }
    let start = start as usize;
    let end = (start + len as usize).min(file.len());
    let mut pos = start;
    while pos < end {
        let (ph, hl) = match parse_page_header(&file[pos..end]) {
            Ok(v) => v,
            Err(_) => break,
        };
        let (nv, nr, enc) = if let Some(d) = &ph.data {
            (Some(d.num_values), None, Some(d.encoding))
        } else if let Some(d) = &ph.data_v2 {
            (Some(d.num_values), Some(d.num_rows), Some(d.encoding))
        } else if let Some(d) = &ph.dict {
            (Some(d.num_values), None, Some(d.encoding))
        } else {
            (None, None, None)
        };
        out.push(PageInfo {
            page_type: ph.page_type,
            compressed_size: ph.compressed_size,
            uncompressed_size: ph.uncompressed_size,
            num_values: nv,
            num_rows: nr,
            encoding: enc,
            header_size: hl,
        });
        if ph.compressed_size < 0 {
            break;
        }
        pos += hl + ph.compressed_size as usize;
    }
    out
}

pub struct LeafInfo {
    pub ptype: PhysType,
    pub type_length: usize,
    pub max_def: u16,
    pub max_rep: u16,
}

fn decode_plain(buf: &[u8], pos: &mut usize, li: &LeafInfo, n: usize, out: &mut Vec<PVal>) -> R<()> {
    match li.ptype {
        PhysType::Boolean => {
            let mut bits = Vec::new();
            let start_bit = *pos * 8;
            unpack_bits(buf, start_bit, 1, n, &mut bits);
            for b in bits {
                out.push(PVal::Bool(b == 1));
            }
            *pos += (n + 7) / 8;
        }
        PhysType::Int32 | PhysType::Float => {
            if *pos + 4 * n > buf.len() {
                return Err(spec_err("not enough values in page"));
            }
            for i in 0..n {
                let o = *pos + 4 * i;
                let a = [buf[o], buf[o + 1], buf[o + 2], buf[o + 3]];
                out.push(if li.ptype == PhysType::Int32 {
                    PVal::I32(i32::from_le_bytes(a))
                } else {
                    PVal::F32(f32::from_le_bytes(a))
                });
            }
            *pos += 4 * n;
        }
        PhysType::Int64 | PhysType::Double => {
            if *pos + 8 * n > buf.len() {
                return Err(spec_err("not enough values in page"));
            }
            for i in 0..n {
                let o = *pos + 8 * i;
                let mut a = [0u8; 8];
                a.copy_from_slice(&buf[o..o + 8]);
                out.push(if li.ptype == PhysType::Int64 {
                    PVal::I64(i64::from_le_bytes(a))
                } else {
                    PVal::F64(f64::from_le_bytes(a))
                });
            }
            *pos += 8 * n;
        }
        PhysType::Int96 => {
            if *pos + 12 * n > buf.len() {
                return Err(spec_err("not enough values in page"));
            }
            for i in 0..n {
                let o = *pos + 12 * i;
                let mut a = [0u8; 12];
                a.copy_from_slice(&buf[o..o + 12]);
                out.push(PVal::I96(a));
            }
            *pos += 12 * n;
        }
        PhysType::ByteArray => {
            for _ in 0..n {
                if *pos + 4 > buf.len() {
                    return Err(spec_err("not enough values in page"));
                }
                let l = u32::from_le_bytes([buf[*pos], buf[*pos + 1], buf[*pos + 2], buf[*pos + 3]]) as usize;
                *pos += 4;
                if *pos + l > buf.len() {
                    return Err(spec_err("not enough values in page"));
                }
                out.push(PVal::Bytes(buf[*pos..*pos + l].to_vec()));
                *pos += l;
            }
        }
        PhysType::FixedLenByteArray => {
            let tl = li.type_length;
            if *pos + tl * n > buf.len() {
                return Err(spec_err("not enough values in page"));
            }
            for _ in 0..n {
                out.push(PVal::Bytes(buf[*pos..*pos + tl].to_vec()));
                *pos += tl;
            }
        }
    }
    Ok(())
}

fn delta_length(buf: &[u8], n: usize) -> R<Vec<Vec<u8>>> {
    let (lens, used) = delta_binary_packed(buf, n)?;
    let mut pos = used;
    let mut out = Vec::with_capacity(lens.len());
    for l in lens {
        let l = l.max(0) as usize;
        if pos + l > buf.len() {
            return Err(spec_err("delta length byte array out of bounds"));
        }
        out.push(buf[pos..pos + l].to_vec());
        pos += l;
    }
    Ok(out)
}

fn decode_values(
    buf: &[u8],
    encoding: i32,
    li: &LeafInfo,
    n: usize,
    dict: &Option<Vec<PVal>>,
    out: &mut Vec<PVal>,
) -> R<()> {
    match encoding {
        0 => {
            let mut pos = 0;
            decode_plain(buf, &mut pos, li, n, out)
        }
        2 | 8 => {
            let d = match dict {
                Some(d) => d,
                None => return Err(spec_err("dictionary page missing")),
            };
            if n == 0 {
                return Ok(());
            }
            if buf.is_empty() {
                return Err(spec_err("dictionary indices missing"));
            }
            let bw = buf[0] as u32;
            let idx = rle_hybrid(&buf[1..], bw, n)?;
            for i in idx {
                let i = i as usize;
                if i >= d.len() {
                    return Err(spec_err("dictionary index out of bounds"));
                }
                out.push(d[i].clone());
            }
            Ok(())
        }
        3 => {
            // RLE booleans with 4-byte length prefix
            let data = if buf.len() >= 4 { &buf[4..] } else { buf };
            let v = rle_hybrid(data, 1, n)?;
            for b in v {
                out.push(PVal::Bool(b == 1));
            }
            Ok(())
        }
        5 => {
            let (vals, _) = delta_binary_packed(buf, n)?;
            for v in vals.into_iter().take(n) {
                out.push(match li.ptype {
                    PhysType::Int32 => PVal::I32(v as i32),
                    _ => PVal::I64(v),
                });
            }
            Ok(())
        }
        6 => {
            for v in delta_length(buf, n)?.into_iter().take(n) {
                out.push(PVal::Bytes(v));
            }
            Ok(())
        }
        7 => {
            let (prefixes, used) = delta_binary_packed(buf, n)?;
            let suffixes = delta_length(&buf[used..], n)?;
            let mut prev: Vec<u8> = Vec::new();
            for (p, s) in prefixes.iter().zip(suffixes.into_iter()) {
                let p = (*p).max(0) as usize;
                let mut v = prev[..p.min(prev.len())].to_vec();
                v.extend_from_slice(&s);
                prev = v.clone();
                out.push(PVal::Bytes(v));
            }
            Ok(())
        }
        9 => {
            let size = match li.ptype {
                PhysType::Float | PhysType::Int32 => 4,
                PhysType::Double | PhysType::Int64 => 8,
                PhysType::FixedLenByteArray => li.type_length,
                _ => return Err(spec_err("byte stream split unsupported type")),
            };
            if size == 0 {
                return Ok(());
            }
            let total = buf.len() / size;
            let mut tmp = vec![0u8; size * n];
            for j in 0..n.min(total) {
                for b in 0..size {
                    tmp[j * size + b] = buf[b * total + j];
                }
            }
            let mut pos = 0;
            decode_plain(&tmp, &mut pos, li, n.min(total), out)
        }
        _ => Err(spec_err(&format!("unsupported encoding {}", encoding))),
    }
}

fn read_levels_v1(buf: &[u8], pos: &mut usize, enc: i32, max: u16, n: usize) -> R<Vec<u16>> {
    if max == 0 {
        return Ok(vec![0; n]);
    }
    let bw = bit_width(max);
    if enc == 4 {
        let nbytes = (n * bw as usize + 7) / 8;
        let end = (*pos + nbytes).min(buf.len());
        let v = bit_packed_legacy(&buf[*pos..end], bw, n);
        *pos += nbytes;
        return Ok(v.into_iter().map(|x| x as u16).collect());
    }
    if *pos + 4 > buf.len() {
        return Err(spec_err("levels truncated"));
    }
    let l = u32::from_le_bytes([buf[*pos], buf[*pos + 1], buf[*pos + 2], buf[*pos + 3]]) as usize;
    *pos += 4;
    if *pos + l > buf.len() {
        return Err(spec_err("levels truncated"));
    }
    let v = rle_hybrid(&buf[*pos..*pos + l], bw, n)?;
    *pos += l;
    Ok(v.into_iter().map(|x| x as u16).collect())
}

/// Read a column chunk up to `max_rows` top-level rows.
pub fn read_column(file: &[u8], cm: &ColumnMeta, li: &LeafInfo, max_rows: usize) -> R<ColumnData> {
    let (start, len) = chunk_range(cm);
    let mut data = ColumnData { def: vec![], rep: vec![], values: vec![] };
    if max_rows == 0 {
        return Ok(data);
    }
    if start < 0 || len < 0 || start as usize > file.len() {
        return Err(spec_err("column chunk out of bounds"));
    }
    let start = start as usize;
    let end = start.saturating_add(len as usize);
    let chunk_end = end.min(file.len());
    let mut pos = start;
    let mut dict: Option<Vec<PVal>> = None;
    let mut rows = 0usize;
    let mut total_values: i64 = 0;
    while pos < chunk_end && total_values < cm.num_values {
        let (ph, hl) = parse_page_header(&file[pos..chunk_end]).map_err(|_| spec_err("invalid page header"))?;
        if ph.compressed_size < 0 || ph.uncompressed_size < 0 {
            return Err(spec_err(
                "Number must be zero or positive: out of range integral type conversion attempted",
            ));
        }
        let body_start = pos + hl;
        let body_end = body_start + ph.compressed_size as usize;
        if body_end > chunk_end {
            return Err(spec_err("The page header reported the wrong page size"));
        }
        let body = &file[body_start..body_end];
        pos = body_end;
        match ph.page_type {
            2 => {
                let dh = ph.dict.clone().ok_or_else(|| spec_err("dictionary page header missing"))?;
                if dh.num_values < 0 {
                    return Err(spec_err(
                        "Number must be zero or positive: out of range integral type conversion attempted",
                    ));
                }
                let raw = compress::decompress(cm.codec, body, ph.uncompressed_size as usize)
                    .map_err(|e| spec_err(&e))?;
                let mut vals = Vec::new();
                let mut p = 0;
                decode_plain(&raw, &mut p, li, dh.num_values as usize, &mut vals)?;
                dict = Some(vals);
            }
            0 => {
                let dh = ph.data.clone().ok_or_else(|| spec_err("data page header missing"))?;
                if dh.num_values < 0 {
                    return Err(spec_err(
                        "Number must be zero or positive: out of range integral type conversion attempted",
                    ));
                }
                let n = dh.num_values as usize;
                let raw = compress::decompress(cm.codec, body, ph.uncompressed_size as usize)
                    .map_err(|e| spec_err(&e))?;
                let mut p = 0usize;
                let rep = read_levels_v1(&raw, &mut p, dh.rep_encoding, li.max_rep, n)?;
                let def = read_levels_v1(&raw, &mut p, dh.def_encoding, li.max_def, n)?;
                let nn = def.iter().filter(|&&d| d == li.max_def).count();
                let mut vals = Vec::new();
                decode_values(&raw[p.min(raw.len())..], dh.encoding, li, nn, &dict, &mut vals)?;
                total_values += n as i64;
                rows += append(&mut data, rep, def, vals, li, max_rows, rows);
            }
            3 => {
                let dh = ph.data_v2.clone().ok_or_else(|| spec_err("data page header missing"))?;
                if dh.num_values < 0 || dh.rep_len < 0 || dh.def_len < 0 {
                    return Err(spec_err(
                        "Number must be zero or positive: out of range integral type conversion attempted",
                    ));
                }
                let n = dh.num_values as usize;
                let rl = dh.rep_len as usize;
                let dl = dh.def_len as usize;
                if rl + dl > body.len() {
                    return Err(spec_err("levels out of bounds"));
                }
                let rep = if li.max_rep > 0 {
                    rle_hybrid(&body[..rl], bit_width(li.max_rep), n)?.into_iter().map(|x| x as u16).collect()
                } else {
                    vec![0; n]
                };
                let def = if li.max_def > 0 {
                    rle_hybrid(&body[rl..rl + dl], bit_width(li.max_def), n)?.into_iter().map(|x| x as u16).collect()
                } else {
                    vec![0; n]
                };
                let vbody = &body[rl + dl..];
                let raw = if dh.is_compressed && cm.codec != 0 {
                    let us = (ph.uncompressed_size as usize).saturating_sub(rl + dl);
                    compress::decompress(cm.codec, vbody, us).map_err(|e| spec_err(&e))?
                } else {
                    vbody.to_vec()
                };
                let nn = def.iter().filter(|&&d| d == li.max_def).count();
                let mut vals = Vec::new();
                decode_values(&raw, dh.encoding, li, nn, &dict, &mut vals)?;
                total_values += n as i64;
                rows += append(&mut data, rep, def, vals, li, max_rows, rows);
            }
            _ => {}
        }
        if rows >= max_rows {
            break;
        }
    }
    Ok(data)
}

/// Append page levels/values, stopping once max_rows rows are complete. Returns rows added.
fn append(
    data: &mut ColumnData,
    rep: Vec<u16>,
    def: Vec<u16>,
    vals: Vec<PVal>,
    li: &LeafInfo,
    max_rows: usize,
    rows_before: usize,
) -> usize {
    let mut rows = rows_before;
    let mut vi = 0usize;
    let mut vals = vals.into_iter();
    for i in 0..def.len() {
        let r = rep[i];
        if r == 0 {
            if rows >= max_rows {
                break;
            }
            rows += 1;
        }
        data.rep.push(r);
        data.def.push(def[i]);
        if def[i] == li.max_def {
            match vals.next() {
                Some(v) => data.values.push(v),
                None => {
                    // missing values: treat as null-ish by lowering def level
                    let l = data.def.len();
                    data.def[l - 1] = li.max_def.saturating_sub(1);
                }
            }
            vi += 1;
        }
    }
    let _ = vi;
    rows - rows_before
}
