//! Schema tree construction.
use super::meta::*;

#[derive(Debug, Clone)]
pub struct SNode {
    pub elem: SchemaElement,
    pub children: Vec<SNode>,
    pub def: u16, // def level counting this node
    pub rep: u16, // rep level counting this node
    pub leaf_index: Option<usize>,
    pub path: Vec<String>,
}

impl SNode {
    pub fn is_leaf(&self) -> bool {
        self.children.is_empty() && self.elem.num_children.unwrap_or(0) == 0 && self.elem.ptype.is_some()
    }
    pub fn repetition(&self) -> Repetition {
        self.elem.repetition.unwrap_or(Repetition::Required)
    }
    pub fn first_leaf(&self) -> Option<usize> {
        if let Some(i) = self.leaf_index {
            return Some(i);
        }
        self.children.iter().find_map(|c| c.first_leaf())
    }
    pub fn leaves(&self, out: &mut Vec<usize>) {
        if let Some(i) = self.leaf_index {
            out.push(i);
        }
        for c in &self.children {
            c.leaves(out);
        }
    }
}

pub fn build_tree(schema: &[SchemaElement]) -> Result<SNode, String> {
    if schema.is_empty() {
        return Err("Parquet error: Root schema element missing".into());
    }
    let mut idx = 0usize;
    let mut leaf = 0usize;
    fn rec(
        schema: &[SchemaElement],
        idx: &mut usize,
        leaf: &mut usize,
        pdef: u16,
        prep: u16,
        path: &[String],
        is_root: bool,
    ) -> Result<SNode, String> {
        if *idx >= schema.len() {
            return Err("Parquet error: Index out of bound".into());
        }
        let e = schema[*idx].clone();
        *idx += 1;
        let (mut def, mut rep) = (pdef, prep);
        if !is_root {
            match e.repetition.unwrap_or(Repetition::Required) {
                Repetition::Optional => def += 1,
                Repetition::Repeated => {
                    def += 1;
                    rep += 1
                }
                _ => {}
            }
        }
        let mut p = path.to_vec();
        if !is_root {
            p.push(e.name.clone());
        }
        let nc = e.num_children.unwrap_or(0);
        let mut children = Vec::new();
        let mut leaf_index = None;
        if nc > 0 {
            for _ in 0..nc {
                children.push(rec(schema, idx, leaf, def, rep, &p, false)?);
            }
        } else if !is_root {
            leaf_index = Some(*leaf);
            *leaf += 1;
        }
        Ok(SNode { elem: e, children, def, rep, leaf_index, path: p })
    }
    let root = rec(schema, &mut idx, &mut leaf, 0, 0, &[], true)?;
    Ok(root)
}

/// Collect leaf nodes in order.
pub fn leaf_nodes<'a>(n: &'a SNode, out: &mut Vec<&'a SNode>) {
    if n.leaf_index.is_some() {
        out.push(n);
    }
    for c in &n.children {
        leaf_nodes(c, out);
    }
}
EOF"}

