impl<'a> Assembler<'a> {
    fn peek(&self, leaf: usize) -> Option<(u16, u16)> {
        let c = &self.cols[leaf];
        let i = self.cur[leaf].lvl;
        if i < c.def.len() {
            Some((c.rep[i], c.def[i]))
        } else {
            None
        }
    }
    fn consume(&mut self, leaf: usize) -> Option<PVal> {
        let c = &self.cols[leaf];
        let i = self.cur[leaf].lvl;
        if i >= c.def.len() {
            return None;
        }
        self.cur[leaf].lvl += 1;
