        for &l in &node.leaves {
            self.consume(l);
        }
    }
    fn read(&mut self, node: &LNode) -> Value {
        let (_, d) = match self.peek(node.first_leaf) {
            Some(x) => x,
            None => return Value::Null,
        };
        match &node.kind {
            LKind::Prim(li) => {
                let li = *li;
                match self.consume(li) {
                    Some(v) => convert_value(v, self.elems[li]),
                    None => Value::Null,
                }
            }
            LKind::Struct(fields) => {
                if node.nullable && d < node.def {
                    self.consume_null(node);
                    return Value::Null;
