                Value::List(items)
            }
        }
    }
}

fn i96_to_ns(b: &[u8; 12]) -> i64 {
    let mut a = [0u8; 8];
    a.copy_from_slice(&b[0..8]);
    let nanos = i64::from_le_bytes(a);
    let days = i32::from_le_bytes([b[8], b[9], b[10], b[11]]) as i64;
    (days - 2440588).wrapping_mul(86_400_000_000_000).wrapping_add(nanos)
}

fn be_i128(b: &[u8]) -> i128 {
    let mut v: i128 = if !b.is_empty() && b[0] & 0x80 != 0 { -1 } else { 0 };
    for &x in b.iter().take(16) {
        v = (v << 8) | x as i128;
    }
    v
}

#[derive(Debug, Clone, PartialEq)]
pub enum Kind {
    Default,
    Signed(u8),
    Unsigned(u8),
    Date,
    TimeMs,
    TimeUs,
    TimeNs,
    Ts(TimeUnit, bool),
    Decimal(u32),
    Str,
    Bin,
    Null,
}

pub fn leaf_kind(e: &SchemaElement) -> Kind {
    let pt = e.ptype.unwrap_or(PhysType::Int32);
    if let Some(l) = &e.logical {
        match l {
            LogicalType::String | LogicalType::Enum | LogicalType::Json => {
                if pt == PhysType::ByteArray {
                    return Kind::Str;
                }
            }
            LogicalType::Integer { bits, signed } => {
                return if *signed { Kind::Signed(*bits as u8) } else { Kind::Unsigned(*bits as u8) };
            }
            LogicalType::Date => return Kind::Date,
            LogicalType::Time { unit, .. } => {
                return match unit {
                    TimeUnit::Millis => Kind::TimeMs,
                    TimeUnit::Micros => Kind::TimeUs,
                    TimeUnit::Nanos => Kind::TimeNs,
                }
            }
            LogicalType::Timestamp { unit, utc } => return Kind::Ts(*unit, *utc),
            LogicalType::Decimal { scale, .. } => {
                if pt != PhysType::ByteArray {
                    return Kind::Decimal(*scale as u32);
                }
                return Kind::Bin;
            }
            LogicalType::Unknown => return Kind::Null,
            _ => {}
        }
    }
    match (pt, e.converted) {
        (PhysType::ByteArray, Some(0)) | (PhysType::ByteArray, Some(4)) | (PhysType::ByteArray, Some(19)) => {
            Kind::Str
        }
        (_, Some(15)) => Kind::Signed(8),
        (_, Some(16)) => Kind::Signed(16),
        (_, Some(17)) => Kind::Signed(32),
        (_, Some(18)) => Kind::Signed(64),
        (_, Some(11)) => Kind::Unsigned(8),
        (_, Some(12)) => Kind::Unsigned(16),
        (_, Some(13)) => Kind::Unsigned(32),
        (_, Some(14)) => Kind::Unsigned(64),
        (PhysType::Int32, Some(6)) => Kind::Date,
        (PhysType::Int32, Some(7)) => Kind::TimeMs,
        (PhysType::Int64, Some(8)) => Kind::TimeUs,
        (PhysType::Int64, Some(9)) => Kind::Ts(TimeUnit::Millis, false),
        (PhysType::Int64, Some(10)) => Kind::Ts(TimeUnit::Micros, false),
        (PhysType::ByteArray, Some(5)) => Kind::Bin,
        (_, Some(5)) => Kind::Decimal(e.scale.unwrap_or(0).max(0) as u32),
        _ => Kind::Default,
    }
}

pub fn convert_value(v: PVal, e: &SchemaElement) -> Value {
    let kind = leaf_kind(e);
    if kind == Kind::Null {
        return Value::Null;
    }
    match v {
        PVal::Bool(b) => Value::Bool(b),
        PVal::I32(x) => match kind {
            Kind::Unsigned(8) => Value::UInt(x as u8 as u64),
            Kind::Unsigned(16) => Value::UInt(x as u16 as u64),
            Kind::Unsigned(_) => Value::UInt(x as u32 as u64),
            Kind::Signed(8) => Value::Int(x as i8 as i64),
            Kind::Signed(16) => Value::Int(x as i16 as i64),
            Kind::Date => Value::Date(x),
            Kind::TimeMs => Value::Time(x as i64 * 1_000_000),
            Kind::Decimal(s) => Value::Decimal(x as i128, s),
            _ => Value::Int(x as i64),
        },
        PVal::I64(x) => match kind {
            Kind::Unsigned(_) => Value::UInt(x as u64),
            Kind::Ts(u, utc) => Value::Datetime(x, u, if utc { Some("UTC".to_string()) } else { None }),
            Kind::TimeUs => Value::Time(x.wrapping_mul(1000)),
            Kind::TimeNs => Value::Time(x),
            Kind::TimeMs => Value::Time(x.wrapping_mul(1_000_000)),
            Kind::Decimal(s) => Value::Decimal(x as i128, s),
            _ => Value::Int(x),
        },
        PVal::I96(b) => Value::Datetime(i96_to_ns(&b), TimeUnit::Nanos, None),
        PVal::F32(f) => Value::F32(f),
        PVal::F64(f) => Value::F64(f),
        PVal::Bytes(b) => match kind {
            Kind::Str => Value::Str(String::from_utf8_lossy(&b).into_owned()),
            Kind::Decimal(s) => Value::Decimal(be_i128(&b), s),
            _ => Value::Bin(b),
        },
    }
}

pub struct Frame {
    pub columns: Vec<String>,
    pub rows: Vec<Vec<Value>>,
}

/// Read up to `limit` rows across row groups.
pub fn read_frame(file: &[u8], meta: &FileMeta, root: &SNode, limit: usize) -> Result<Frame, String> {
    let fields = logical_fields(root);
    let columns: Vec<String> = fields.iter().map(|f| f.name.clone()).collect();
    let mut leaves = Vec::new();
    leaf_nodes(root, &mut leaves);
    let total = (meta.num_rows.max(0) as usize).min(limit);
    let mut rows: Vec<Vec<Value>> = Vec::new();
    for rg in &meta.row_groups {
        if rows.len() >= total {
            break;
        }
        let want = (total - rows.len()).min(rg.num_rows.max(0) as usize);
        if want == 0 {
            continue;
        }
        let mut cols = Vec::with_capacity(leaves.len());
        for (i, ln) in leaves.iter().enumerate() {
            let cc = rg.columns.get(i).and_then(|c| c.meta.as_ref());
            let cm = match cc {
                Some(c) => c,
                None => return Err("parquet: File out of specification: column metadata missing".into()),
            };
            let li = LeafInfo {
                ptype: ln.elem.ptype.unwrap_or(PhysType::Int32),
                type_length: ln.elem.type_length.unwrap_or(0).max(0) as usize,
                max_def: ln.def,
                max_rep: ln.rep,
            };
            cols.push(read_column(file, cm, &li, want)?);
        }
        let mut asm = Assembler {
            cols: &cols,
            max_def: leaves.iter().map(|l| l.def).collect(),
            elems: leaves.iter().map(|l| &l.elem).collect(),
            cur: (0..leaves.len()).map(|_| Cursor { lvl: 0, val: 0 }).collect(),
        };
        for _ in 0..want {
            let mut row = Vec::with_capacity(fields.len());
            for f in &fields {
                row.push(asm.read(f));
            }
            rows.push(row);
        }
    }
    Ok(Frame { columns, rows })
}
