//! Value formatting mimicking polars' AnyValue display.
use crate::data::Value;
use crate::pq::meta::TimeUnit;
use std::fmt::Write;

pub fn fmt_float(v: f64) -> String {
    const BOUND: f64 = 999999.0;
    if v.fract() == 0.0 && v.abs() < BOUND {
        return format!("{:.1}", v);
    }
    let plain = format!("{}", v);
    if plain.len() > 9 {
        if !(0.000001..=BOUND).contains(&v.abs()) || v.abs() > BOUND {
            return format!("{:.4e}", v);
        }
        let s = format!("{:.6}", v);
        if s.ends_with('0') {
            let mut t: &str = s.as_str();
            while t.ends_with('0') {
                t = &t[..t.len() - 1];
            }
            if t.ends_with('.') {
                return format!("{}0", t);
            }
            return t.to_string();
        }
        return s;
    }
    if v.fract() == 0.0 {
        format!("{:e}", v)
    } else {
        plain
    }
}

pub fn fmt_bytes(b: &[u8]) -> String {
    let width = 60;
    let mut s = String::from("b\"");
    for &c in b.iter().take(width) {
        if c.is_ascii_alphanumeric() || c.is_ascii_punctuation() {
            s.push(c as char);
        } else {
            let _ = write!(s, "\\x{:02x}", c);
        }
    }
    if b.len() > width {
        s.push_str("\"…");
    } else {
        s.push('"');
    }
    s
}

/// Convert days since epoch to (year, month, day).
pub fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

fn fmt_year(y: i64) -> String {
    if (0..=9999).contains(&y) {
        format!("{:04}", y)
    } else {
        format!("{:+05}", y)
    }
}

pub fn fmt_date(days: i64) -> String {
    let (y, m, d) = civil_from_days(days);
    format!("{}-{:02}-{:02}", fmt_year(y), m, d)
}

fn fmt_frac(nanos: i64) -> String {
    if nanos == 0 {
        String::new()
    } else if nanos % 1_000_000 == 0 {
        format!(".{:03}", nanos / 1_000_000)
    } else if nanos % 1_000 == 0 {
        format!(".{:06}", nanos / 1_000)
    } else {
        format!(".{:09}", nanos)
    }
}

pub fn fmt_time_ns(ns: i64) -> String {
    let secs = ns.div_euclid(1_000_000_000);
    let nanos = ns.rem_euclid(1_000_000_000);
    let secs = secs.rem_euclid(86400);
    format!("{:02}:{:02}:{:02}{}", secs / 3600, (secs / 60) % 60, secs % 60, fmt_frac(nanos))
}

pub fn fmt_datetime(v: i64, unit: TimeUnit) -> String {
    let (secs, nanos) = match unit {
        TimeUnit::Millis => (v.div_euclid(1000), v.rem_euclid(1000) * 1_000_000),
        TimeUnit::Micros => (v.div_euclid(1_000_000), v.rem_euclid(1_000_000) * 1000),
        TimeUnit::Nanos => (v.div_euclid(1_000_000_000), v.rem_euclid(1_000_000_000)),
    };
    let days = secs.div_euclid(86400);
    let sod = secs.rem_euclid(86400);
    format!(
        "{} {:02}:{:02}:{:02}{}",
        fmt_date(days),
        sod / 3600,
        (sod / 60) % 60,
        sod % 60,
        fmt_frac(nanos)
    )
}

pub fn fmt_decimal(v: i128, scale: u32) -> String {
    if scale == 0 {
        return v.to_string();
    }
    let neg = v < 0;
    let a = v.unsigned_abs();
    let p = 10u128.pow(scale.min(38));
    let int = a / p;
    let frac = a % p;
    format!("{}{}.{:0width$}", if neg { "-" } else { "" }, int, frac, width = scale as usize)
}

pub fn fmt_list(items: &[Value]) -> String {
    if items.is_empty() {
        return "[]".to_string();
    }
    let max_items = 3usize;
    let mut s = String::from("[");
    if max_items >= items.len() {
        for (i, it) in items.iter().enumerate() {
            if i > 0 {
                s.push_str(", ");
            }
            s.push_str(&fmt_value(it));
        }
        s.push(']');
    } else {
        for (i, it) in items.iter().take(max_items).enumerate() {
            if i == max_items - 1 {
                let _ = write!(s, "… {}", fmt_value(&items[items.len() - 1]));
                break;
            } else {
                let _ = write!(s, "{}, ", fmt_value(it));
            }
        }
        s.push(']');
    }
    s
}

pub fn fmt_value(v: &Value) -> String {
    match v {
        Value::Null => "null".to_string(),
        Value::Bool(b) => b.to_string(),
        Value::Int(i) => i.to_string(),
        Value::UInt(u) => u.to_string(),
        Value::F32(f) => fmt_float(*f as f64),
        Value::F64(f) => fmt_float(*f),
        Value::Str(s) => format!("\"{}\"", s),
        Value::Bin(b) => fmt_bytes(b),
        Value::Date(d) => fmt_date(*d as i64),
        Value::Datetime(v, u, tz) => match tz {
            None => fmt_datetime(*v, *u),
            Some(t) => format!("{} {}", fmt_datetime(*v, *u), t),
        },
        Value::Time(ns) => fmt_time_ns(*ns),
        Value::Decimal(v, s) => fmt_decimal(*v, *s),
        Value::List(items) => fmt_list(items),
        Value::Struct(vals) => {
            let mut s = String::from("{");
            for (i, x) in vals.iter().enumerate() {
                if i > 0 {
                    s.push(',');
                }
                s.push_str(&fmt_value(x));
            }
            s.push('}');
            s
        }
    }
}

pub fn fmt_cell(v: &Value) -> String {
    match v {
        Value::Null => "NULL".to_string(),
        other => fmt_value(other),
    }
}
