//! Loading of the parquet file into the application model.
use crate::data::{read_frame, Frame};
use crate::pq::meta::*;
use crate::pq::schema::{build_tree, SNode};

pub struct Model {
    pub path: String,
    pub file: Vec<u8>,
    pub meta: FileMeta,
    pub root: SNode,
    pub frame: Frame,
}

pub enum LoadError {
    Msg(String),
    Panic(String),
}

pub const ROW_LIMIT: usize = 200;

pub fn load(path: &str) -> Result<Model, LoadError> {
    let file = std::fs::read(path).map_err(|e| LoadError::Msg(io_msg(&e, path)))?;
    let size = file.len();
    if size < 8 {
        return Err(LoadError::Msg(format!("EOF: Parquet file too small. Size is {} but need 8", size)));
    }
    let tail = &file[size - 8..];
    if &tail[4..8] == b"PARE" {
        return Err(LoadError::Msg(
            "Parquet error: Parquet file has an encrypted footer but the encryption feature is disabled".into(),
        ));
    }
    if &tail[4..8] != b"PAR1" {
        return Err(LoadError::Msg("Parquet error: Invalid Parquet file. Corrupt footer".into()));
    }
    let mlen = u32::from_le_bytes([tail[0], tail[1], tail[2], tail[3]]) as usize;
    if mlen + 8 > size {
        return Err(LoadError::Msg(format!("EOF: Parquet file too small. Size is {} but need {}", size, mlen + 8)));
    }
    let mbuf = &file[size - 8 - mlen..size - 8];
    let meta = parse_file_meta(mbuf).map_err(|e| LoadError::Msg(format!("Parquet error: {}", e)))?;
    let root = build_tree(&meta.schema).map_err(LoadError::Msg)?;
    if let Some(p) = crate::arrow_schema::check_timezones(&meta) {
        return Err(LoadError::Panic(p));
    }
    let frame = read_frame(&file, &meta, &root, ROW_LIMIT).map_err(LoadError::Msg)?;
    Ok(Model { path: path.to_string(), file, meta, root, frame })
}

fn io_msg(e: &std::io::Error, _path: &str) -> String {
    e.to_string()
}
