//! Schema tree shared by the Schema and Row Groups tabs.
use crate::pq::schema::SNode;
use ratatui::buffer::Buffer;
use ratatui::layout::Rect;
use ratatui::style::{Color, Modifier, Style};
use ratatui::text::{Line, Span};
use ratatui::widgets::{Block, BorderType, Paragraph, Scrollbar, ScrollbarOrientation, ScrollbarState, StatefulWidget, Widget};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ItemKind {
    Root,
    Group,
    Leaf,
}

#[derive(Clone, Debug)]
pub struct TreeItem<'a> {
    pub label: String,
    pub kind: ItemKind,
    pub leaf: Option<usize>,
    pub node: &'a SNode,
}

pub fn build_items(root: &SNode) -> Vec<TreeItem<'_>> {
    let mut out = Vec::new();
    out.push(TreeItem { label: "└─ root".to_string(), kind: ItemKind::Root, leaf: None, node: root });
    fn rec<'a>(n: &'a SNode, prefix: &str, out: &mut Vec<TreeItem<'a>>) {
        let cnt = n.children.len();
        for (i, c) in n.children.iter().enumerate() {
            let last = i + 1 == cnt;
            let label = format!("{}{}{}", prefix, if last { "└─ " } else { "├─ " }, c.elem.name);
            let is_group = c.leaf_index.is_none();
            out.push(TreeItem {
                label,
                kind: if is_group { ItemKind::Group } else { ItemKind::Leaf },
                leaf: c.leaf_index,
                node: c,
            });
            let np = format!("{}{}", prefix, if last { "   " } else { "│  " });
            rec(c, &np, out);
        }
    }
    rec(root, "   ", &mut out);
    out
}

pub fn max_label_bytes(items: &[TreeItem]) -> usize {
    items.iter().map(|i| i.label.len()).max().unwrap_or(0)
}

/// Next selectable (leaf) index after `sel`.
pub fn next_leaf(items: &[TreeItem], sel: usize) -> usize {
    let mut i = sel + 1;
    while i < items.len() {
        if items[i].kind == ItemKind::Leaf {
            return i;
        }
        i += 1;
    }
    sel
}

pub fn prev_leaf(items: &[TreeItem], sel: usize) -> usize {
    let mut i = sel;
    while i > 0 {
        i -= 1;
        if items[i].kind == ItemKind::Leaf || i == 0 {
            return i;
        }
    }
    0
}

pub fn tree_offset(sel: usize, cap: usize) -> usize {
    if cap == 0 {
        return sel;
    }
    sel.saturating_sub(cap - 1)
}

/// Render the tree block into `area` and an optional scrollbar into `sb_area`.
pub fn render_tree(items: &[TreeItem], sel: usize, area: Rect, sb_area: Option<Rect>, buf: &mut Buffer) {
    let mut bottom = vec![
        Span::styled("Leaf", Style::default().fg(Color::White)),
        Span::raw(", "),
        Span::styled("Group", Style::default().fg(Color::Green)),
    ];
    if sel > 0 {
        bottom.push(Span::raw(", "));
        bottom.push(Span::styled("Selected", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)));
    }
    let block = Block::bordered()
        .border_type(BorderType::Rounded)
        .title(Line::from(Span::styled("Schema Tree", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))).centered())
        .title_bottom(Line::from(bottom).centered());
    let inner = block.inner(area);
    block.render(area, buf);
    let cap = inner.height as usize;
    let off = tree_offset(sel, cap);
    let mut lines = Vec::new();
    for (i, it) in items.iter().enumerate().skip(off).take(cap) {
        let style = if i == sel && sel > 0 {
            Style::default().fg(Color::Black).bg(Color::Yellow)
        } else {
            match it.kind {
                ItemKind::Root => Style::default().fg(Color::LightYellow),
                ItemKind::Group => Style::default().fg(Color::Green),
                ItemKind::Leaf => Style::default().fg(Color::White),
            }
        };
        lines.push(Line::from(it.label.clone()).style(style));
    }
    for (k, l) in lines.into_iter().enumerate() {
        let r = Rect { x: inner.x, y: inner.y + k as u16, width: inner.width, height: 1 };
        let st = l.style;
        buf.set_style(r, st);
        Paragraph::new(l).render(r, buf);
    }
    if let Some(sb) = sb_area {
        let mut state = ScrollbarState::new(items.len()).position(off);
        Scrollbar::new(ScrollbarOrientation::VerticalRight)
            .begin_symbol(None)
            .end_symbol(None)
            .track_symbol(Some("│"))
            .thumb_symbol("█")
            .track_style(Style::default().fg(Color::Yellow))
            .thumb_style(Style::default().fg(Color::Gray))
            .render(sb, buf, &mut state);
    }
}
