    pub page: usize,
}

impl Default for VisState {
    fn default() -> Self {
        VisState { sel: 0, off: 0, col: 0, page: 1 }
    }
}

pub struct VisCache {
    pub cells: Vec<Vec<String>>, // [row][col]
    pub headers: Vec<String>,
    pub widths: Vec<usize>,
}

const MAX_W: usize = 25;
const MIN_W: usize = 8;

pub fn build_cache(m: &Model) -> VisCache {
    let ncols = m.frame.columns.len();
    let mut widths: Vec<usize> = m.frame.columns.iter().map(|h| h.len()).collect();
    let mut cells = Vec::with_capacity(m.frame.rows.len());
    for row in &m.frame.rows {
        let mut r = Vec::with_capacity(ncols);
        for (j, v) in row.iter().enumerate() {
            let s = fmt_cell(v);
            if j < widths.len() && s.len() > widths[j] {
                widths[j] = s.len();
            }
            let s = if s.len() > MAX_W {
                let mut t: String = s.chars().take(MAX_W - 1).collect();
                t.push('…');
                t
            } else {
                s
            };
            r.push(s);
        }
        cells.push(r);
    }
    let widths = widths.into_iter().map(|w| w.clamp(MIN_W, MAX_W)).collect();
    let headers = m
        .frame
        .columns
        .iter()
        .map(|h| {
            if h.len() > MAX_W {
                let t: String = h.chars().take(MAX_W - 3).collect();
                format!("{}...", t)
            } else {
                h.clone()
            }
        })
        .collect();
    VisCache { cells, headers, widths }
}

pub fn visible_cols(width: u16) -> usize {
    ((width as usize).saturating_sub(9) / 12).max(1)
}

fn put(buf: &mut Buffer, x: u16, y: u16, s: &str, max_w: usize, style: Style) {
    let a = buf.area;
    if y >= a.bottom() || x >= a.right() {
        return;
    }
    let lim = (a.right() - x) as usize;
    buf.set_stringn(x, y, s, max_w.min(lim), style);
}

pub fn render(m: &Model, cache: &VisCache, st: &mut VisState, area: Rect, buf: &mut Buffer) {
    if area.height == 0 {
        return;
    }
    let nrows = cache.cells.len();
    let ncols = cache.headers.len();
    let vis = visible_cols(area.width);
    let col_off = st.col.min(ncols.saturating_sub(vis));
    let cols: Vec<usize> = (col_off..ncols).take(vis).collect();
    let data_rows = (area.height as usize).saturating_sub(2);
    st.page = data_rows.saturating_sub(1).max(1);
    // keep selection visible
    if st.sel >= st.off + st.page {
        st.off = st.sel + 1 - st.page;
    }
    if st.sel < st.off {
        st.off = st.sel;
    }
    let _ = m;
    let header_style = Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD);
    let dim = Style::default().fg(Color::DarkGray);
    // header
    let mut x = area.x as usize + 9;
    for &c in &cols {
        if x < (area.right() as usize) {
            put(buf, x as u16, area.y, &cache.headers[c], cache.widths[c], header_style);
        }
        x += cache.widths[c] + 2;
    }
    let total_w: usize = cols.iter().map(|&c| cache.widths[c] + 2).sum();
    // separator
    if area.height >= 2 {
        let y = area.y + 1;
        for xx in area.left()..area.right() {
            let sym = if xx - area.left() == 6 { "┬" } else { "─" };
            buf[(xx, y)].set_symbol(sym).set_style(dim);
        }
    }
    // rows
    for i in 0..data_rows {
        let y = area.y + 2 + i as u16;
        let r = st.off + i;
        if r < nrows {
            let selected = r == st.sel;
            let num_style = if selected {
                Style::default().add_modifier(Modifier::BOLD | Modifier::UNDERLINED)
            } else {
                dim
            };
            put(buf, area.x, y, &(r + 1).to_string(), 6, num_style);
        }
        if area.width > 6 {
            buf[(area.x + 6, y)].set_symbol("│").set_style(dim);
        }
        if r < nrows {
            let mut x = area.x as usize + 9;
            for &c in &cols {
                if x < area.right() as usize {
                    put(buf, x as u16, y, &cache.cells[r][c], cache.widths[c], Style::default());
                }
                x += cache.widths[c] + 2;
            }
            if r == st.sel {
                let x0 = area.x + 9;
                if x0 < area.right() {
                    let w = (total_w as u16).min(area.right() - x0);
                    buf.set_style(
                        Rect { x: x0, y, width: w, height: 1 },
                        Style::default().fg(Color::White).bg(Color::Rgb(60, 60, 60)).add_modifier(Modifier::BOLD),
                    );
                }
            }
        }
    }
}

pub fn key(st: &mut VisState, code: crossterm::event::KeyCode, nrows: usize, ncols: usize) {
    use crossterm::event::KeyCode::*;
    match code {
        Down => {
            if st.sel + 1 < nrows {
                st.sel += 1;
            }
        }
        Up => {
            st.sel = st.sel.saturating_sub(1);
        }
        Char('d') | Char('D') => {
            if nrows > 0 {
                st.sel = (st.sel + st.page).min(nrows - 1);
            }
        }
        Char('u') | Char('U') => {
            st.sel = st.sel.saturating_sub(st.page);
        }
        Right => {
            if st.col + 1 < ncols {
                st.col += 1;
            }
        }
        Left => {
            st.col = st.col.saturating_sub(1);
        }
        _ => {}
    }
    if st.sel >= st.off + st.page {
        st.off = st.sel + 1 - st.page;
    }
    if st.sel < st.off {
        st.off = st.sel;
    }
}
