//! Metadata tab: file level metadata box.
use super::util::*;
use crate::model::Model;
use crate::pq::meta::{codec_name, encoding_name};
use ratatui::buffer::Buffer;
use ratatui::layout::Rect;
use ratatui::style::{Color, Modifier, Style};
use ratatui::text::{Line, Span};
use ratatui::widgets::{Block, BorderType, Widget};

pub fn lines(m: &Model) -> Vec<(&'static str, String)> {
    let meta = &m.meta;
    let rows: i64 = meta.row_groups.iter().map(|r| r.num_rows).sum();
    let mut raw: i64 = 0;
    let mut comp: i64 = 0;
    let mut codecs: Vec<(i32, usize)> = Vec::new();
    let mut encs: Vec<i32> = Vec::new();
    for rg in &meta.row_groups {
        for c in &rg.columns {
            if let Some(cm) = &c.meta {
                raw += cm.total_uncompressed_size;
                comp += cm.total_compressed_size;
                match codecs.iter_mut().find(|(k, _)| *k == cm.codec) {
                    Some(e) => e.1 += 1,
                    None => codecs.push((cm.codec, 1)),
                }
                for e in &cm.encodings {
                    if !encs.contains(e) {
                        encs.push(*e);
                    }
                }
            }
        }
    }
    let ncols = {
        let mut v = Vec::new();
        m.root.leaves(&mut v);
        v.len()
    };
    let mut enc_names: Vec<String> = encs.iter().map(|e| encoding_name(*e)).collect();
    enc_names.sort();
    enc_names.dedup();
    let mut codec_strs: Vec<(String, usize)> = codecs.iter().map(|(c, n)| (codec_name(*c), *n)).collect();
    codec_strs.sort();
    let codec_line = codec_strs.iter().map(|(c, n)| format!("{}({})", c, n)).collect::<Vec<_>>().join(", ");
    let ratio = if comp > 0 { raw as f64 / comp as f64 } else { 0.0 };
    let avg = if rows > 0 { raw / rows } else { 0 };
    vec![
        ("Format version", meta.version.to_string()),
        ("Created by", meta.created_by.clone().unwrap_or_else(|| "—".to_string())),
        ("Rows", thousands(rows)),
        ("Columns", ncols.to_string()),
        ("Row groups", meta.row_groups.len().to_string()),
        ("Size (raw)", size_iec(raw as f64)),
        ("Size (compressed)", size_iec(comp as f64)),
        ("Compression ratio", format!("{:.2}x", ratio)),
        ("Codecs (cols)", codec_line),
        ("Encodings", enc_names.join(", ")),
        ("Avg row size", format!("{} B", avg)),
    ]
}

pub fn render(m: &Model, area: Rect, buf: &mut Buffer) {
    let ls = lines(m);
    let maxv = ls.iter().map(|(_, v)| v.chars().count()).max().unwrap_or(0);
    let content_w = (maxv + 21) as u16;
    let content_h = ls.len() as u16;
    let x = area.x + area.width.saturating_sub(content_w) / 2;
    let y = area.y + area.height.saturating_sub(content_h) / 2;
    let rect = Rect { x, y, width: content_w + 2, height: content_h + 2 };
    let block = Block::bordered()
        .border_type(BorderType::Rounded)
        .title(Line::from(Span::styled("File Metadata", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))).centered());
    block.render(rect, buf);
    let label_style = Style::default().fg(Color::Blue).add_modifier(Modifier::BOLD);
    let ba = buf.area;
    for (i, (k, v)) in ls.iter().enumerate() {
        let yy = y + 1 + i as u16;
        if yy >= ba.bottom() {
            break;
        }
        let lx = x + 1;
        if lx < ba.right() {
            let lab = format!("{:>18}", k);
            let w = (ba.right() - lx) as usize;
            buf.set_stringn(lx, yy, &lab, w.min(18), label_style);
        }
        let vx = x + 1 + 19;
        if vx < ba.right() {
            let w = (ba.right() - vx) as usize;
            let maxw = (content_w as usize).saturating_sub(19);
            buf.set_stringn(vx, yy, v, w.min(maxw), Style::default());
        }
    }
}
