pub fn aggregate(m: &Model, leaf: usize) -> Option<ColAgg> {
    let mut agg: Option<ColAgg> = None;
    for rg in &m.meta.row_groups {
        let cm: &ColumnMeta = match rg.columns.get(leaf).and_then(|c| c.meta.as_ref()) {
            Some(c) => c,
            None => continue,
        };
        let a = agg.get_or_insert_with(|| ColAgg {
