    let mut rows = Vec::new();
    for (it, (cells, is_group)) in rows_items.iter().zip(all.iter()) {
        let r = Row::new(cols.iter().map(|&c| {
            let s = cells[c].clone();
            if *is_group && (c == 0 || c == 1) {
                Cell::from(Span::styled(s, Style::default().fg(Color::Green)))
            } else {
                Cell::from(s)
            }
        }));
        let r = if hl_leaf.is_some() && it.leaf == hl_leaf {
            r.style(Style::default().fg(Color::Black).bg(Color::Yellow))
        } else {
            r
        };
        rows.push(r);
    }
    let table = Table::new(rows, widths.iter().map(|w| Constraint::Length(*w as u16 + 1)))
        .header(header)
        .column_spacing(1)
        .flex(Flex::Start);
    Widget::render(table, inner, buf);
}

pub fn key(st: &mut SchemaState, items: &[TreeItem], code: crossterm::event::KeyCode) {
    use crossterm::event::KeyCode::*;
    match code {
        Down => st.sel = next_leaf(items, st.sel),
        Up => st.sel = prev_leaf(items, st.sel),
        Right => {
            if st.col + 1 < 10 {
                st.col += 1;
            }
        }
        Left => st.col = st.col.saturating_sub(1),
        _ => {}
    }
}
