//! Row Groups tab.
use super::schema::stat_value;
use super::tree::*;
use super::util::*;
use crate::model::Model;
use crate::pq::column::list_pages;
use crate::pq::meta::{codec_name, encoding_name};
use ratatui::buffer::Buffer;
use ratatui::layout::{Alignment, Constraint, Flex, Layout, Rect};
use ratatui::style::{Color, Modifier, Style};
use ratatui::symbols::Marker;
use ratatui::text::{Line, Span};
use ratatui::widgets::{Axis, Block, BorderType, Borders, Cell, Chart, Dataset, GraphType, Paragraph, Row, Table, Widget};

pub struct RgState {
    pub sel: usize,
    pub rg: usize,
}

impl Default for RgState {
    fn default() -> Self {
        RgState { sel: 0, rg: 0 }
    }
}

pub fn key(st: &mut RgState, items: &[TreeItem], nrg: usize, code: crossterm::event::KeyCode) {
    use crossterm::event::KeyCode::*;
    match code {
        Down => st.sel = next_leaf(items, st.sel),
        Up => st.sel = prev_leaf(items, st.sel),
        Right => {
            if st.rg + 1 < nrg {
                st.rg += 1;
            }
        }
        Left => st.rg = st.rg.saturating_sub(1),
        _ => {}
    }
}

struct RgInfo {
    rows: i64,
    comp: i64,
    unc: i64,
}

fn rg_infos(m: &Model) -> Vec<RgInfo> {
    m.meta
        .row_groups
        .iter()
        .map(|rg| {
            let mut comp = 0;
            let mut unc = 0;
            for c in &rg.columns {
                if let Some(cm) = &c.meta {
                    comp += cm.total_compressed_size;
                    unc += cm.total_uncompressed_size;
                }
            }
            RgInfo { rows: rg.num_rows, comp, unc }
        })
        .collect()
}

fn ratio(unc: i64, comp: i64) -> f64 {
    if comp > 0 {
        unc as f64 / comp as f64
    } else {
        0.0
    }
}

fn median_f(v: &[f64]) -> f64 {
    if v.is_empty() {
        return 0.0;
    }
    let mut s = v.to_vec();
    s.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let n = s.len();
    if n % 2 == 1 {
        s[n / 2]
    } else {
        (s[n / 2 - 1] + s[n / 2]) / 2.0
    }
}

fn mean_f(v: &[f64]) -> f64 {
    if v.is_empty() {
        0.0
    } else {
        v.iter().sum::<f64>() / v.len() as f64
    }
}

pub fn tree_width_rg(items: &[TreeItem], need_sb: bool) -> u16 {
    let b = max_label_bytes(items).max(24);
    (if need_sb { b + 1 } else { b }) as u16
}

pub fn render(m: &Model, items: &[TreeItem], st: &mut RgState, area: Rect, buf: &mut Buffer) {
    let cap = area.height.saturating_sub(2) as usize;
    let need_sb = items.len() > cap;
    let tw = tree_width_rg(items, need_sb).min(area.width);
    let tree_area = Rect { x: area.x, y: area.y, width: tw, height: area.height };
    let mut x = area.x + tw;
    let sb_area = if need_sb && x < area.right() {
        let r = Rect { x, y: area.y, width: 1, height: area.height };
        x += 1;
        Some(r)
    } else {
        None
    };
    render_tree(items, st.sel, tree_area, sb_area, buf);
    if x >= area.right() {
        return;
    }
    let ra = Rect { x, y: area.y, width: area.right() - x, height: area.height };
    let infos = rg_infos(m);
    let n = infos.len();
    if n == 0 {
        return;
    }
    let cur = st.rg.min(n - 1);
    let sel_leaf = if st.sel > 0 { items[st.sel].leaf } else { None };
    let chunks: Vec<Rect> = if sel_leaf.is_some() {
        Layout::vertical([Constraint::Length(3), Constraint::Length(1), Constraint::Length(3), Constraint::Min(0)])
            .split(ra)
            .to_vec()
    } else {
        Layout::vertical([Constraint::Length(3), Constraint::Length(3), Constraint::Min(0)]).split(ra).to_vec()
    };
    // progress block
    let pb = Block::bordered()
        .style(Style::default().fg(Color::Gray))
        .title(Line::from(format!(" Row Group: {} / {} ", cur + 1, n)).add_modifier(Modifier::BOLD));
    let pin = pb.inner(chunks[0]);
    pb.render(chunks[0], buf);
    if pin.width > 0 && pin.height > 0 {
        let w = pin.width as usize;
        let s = cur * w / n;
        let e = (cur + 1) * w / n;
        for i in 0..w {
            let (sym, col) = if i >= s && i < e { ("█", Color::Blue) } else { ("─", Color::White) };
            buf[(pin.x + i as u16, pin.y)].set_symbol(sym).set_style(Style::default().fg(col));
        }
    }
    if let Some(leaf) = sel_leaf {
        render_column(m, items, st.sel, leaf, cur, &chunks[1..], buf);
        return;
    }
    // summary boxes
    let rows_v: Vec<f64> = infos.iter().map(|i| i.rows as f64).collect();
    let comp_v: Vec<f64> = infos.iter().map(|i| i.comp as f64).collect();
    let unc_v: Vec<f64> = infos.iter().map(|i| i.unc as f64).collect();
    let ratio_v: Vec<f64> = infos.iter().map(|i| ratio(i.unc, i.comp)).collect();
    let c = &infos[cur];
    let boxes = [
        ("Rows", thousands(c.rows), thousands(mean_f(&rows_v) as i64), thousands(median_f(&rows_v) as i64)),
        ("Compressed", size_iec(c.comp as f64), size_iec(mean_f(&comp_v)), size_iec(median_f(&comp_v))),
        ("Uncompressed", size_iec(c.unc as f64), size_iec(mean_f(&unc_v)), size_iec(median_f(&unc_v))),
        (
            "Ratio",
            format!("{:.2}", ratio(c.unc, c.comp)),
            format!("{:.2}", mean_f(&ratio_v)),
            format!("{:.2}", median_f(&ratio_v)),
        ),
    ];
    let cols = Layout::horizontal([Constraint::Ratio(1, 4); 4]).split(chunks[1]);
    for (i, (title, val, avg, med)) in boxes.iter().enumerate() {
        let b = Block::bordered()
            .border_style(Style::default().fg(Color::Blue))
            .title(Span::styled(*title, Style::default().fg(Color::LightBlue).add_modifier(Modifier::BOLD)))
            .title_bottom(
                Line::from(vec![
                    Span::styled(avg.clone(), Style::default().fg(Color::LightCyan)),
                    Span::styled(" / ", Style::default().fg(Color::White)),
                    Span::styled(med.clone(), Style::default().fg(Color::LightMagenta)),
                ])
                .add_modifier(Modifier::BOLD)
                .centered(),
            );
        let inner = b.inner(cols[i]);
        b.render(cols[i], buf);
        Paragraph::new(Span::styled(val.clone(), Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)))
            .alignment(Alignment::Center)
            .render(inner, buf);
    }
    // charts
    let lower = Layout::horizontal([Constraint::Percentage(50), Constraint::Percentage(50)]).split(chunks[2]);
    let charts = Layout::vertical([Constraint::Percentage(50), Constraint::Percentage(50)]).split(lower[0]);
    let xb = [0.5, n as f64 + 0.5];
    let xlabels: Vec<String> = {
        let mut v: Vec<usize> = (0..4).map(|k| 1 + k * (n - 1) / 3).collect();
        v.dedup();
        v.iter().map(|x| x.to_string()).collect()
    };
    let comp_pts: Vec<(f64, f64)> = infos.iter().enumerate().map(|(i, r)| ((i + 1) as f64, r.comp as f64)).collect();
    let unc_pts: Vec<(f64, f64)> = infos.iter().enumerate().map(|(i, r)| ((i + 1) as f64, r.unc as f64)).collect();
    let maxb = infos.iter().map(|r| r.comp.max(r.unc)).max().unwrap_or(0) as f64;
    let yhi = maxb * 1.5;
    let ylabels: Vec<String> = (0..4).map(|k| fmt_bytes_label(yhi * k as f64 / 4.0)).collect();
    let ds = vec![
        Dataset::default()
            .name("Compressed")
            .marker(Marker::Dot)
            .graph_type(GraphType::Scatter)
            .style(Style::default().fg(Color::Blue))
            .data(&comp_pts),
        Dataset::default()
            .name("Uncompressed")
            .marker(Marker::Dot)
            .graph_type(GraphType::Scatter)
            .style(Style::default().fg(Color::Red))
            .data(&unc_pts),
    ];
    let chart = Chart::new(ds)
        .block(
            Block::new()
                .title(
                    Line::from(vec![
                        Span::styled("Compressed", Style::default().fg(Color::LightBlue).add_modifier(Modifier::BOLD)),
