    let rpts: Vec<(f64, f64)> = ratio_v.iter().enumerate().map(|(i, r)| ((i + 1) as f64, *r)).collect();
    let maxr = ratio_v.iter().cloned().fold(f64::MIN, f64::max);
    let rlo = 1.0;
    let rhi = maxr * 1.1;
    let rlabels: Vec<String> = (0..4).map(|k| format!("{:.1}x", rlo + (rhi - rlo) * k as f64 / 4.0)).collect();
    let ds2 = vec![Dataset::default()
        .marker(Marker::Dot)
        .graph_type(GraphType::Scatter)
        .style(Style::default().fg(Color::Yellow))
        .data(&rpts)];
