fn fmt_bytes_label(v: f64) -> String {
    if v >= 1_000_000.0 {
        format!("{:.1}M", v / 1024.0 / 1024.0)
    } else if v >= 1000.0 {
        format!("{:.1}K", v / 1024.0)
    } else {
        format!("{:.0}", v)
    }
}

fn page_type_name(t: i32) -> &'static str {
    match t {
        0 => "Data Page",
        1 => "Index Page",
        2 => "Dictionary Page",
        3 => "Data Page V2",
        _ => "Unknown",
    }
}

fn render_column(m: &Model, items: &[TreeItem], sel: usize, leaf: usize, rg: usize, chunks: &[Rect], buf: &mut Buffer) {
    let name = items[sel].node.elem.name.clone();
    let hb = Block::new()
        .borders(Borders::TOP)
        .style(Style::default().fg(Color::Blue))
        .title(
            Line::from(vec![
                Span::raw(" Column: "),
                Span::styled(format!("\"{}\"", name), Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
                Span::raw(" "),
            ])
            .centered(),
        );
    hb.render(chunks[0], buf);
    let cc = m.meta.row_groups.get(rg).and_then(|r| r.columns.get(leaf));
    let cm = cc.and_then(|c| c.meta.as_ref());
    let flags = [
        ("Statistics", cm.map_or(false, |c| c.statistics.is_some())),
        ("Dict Page", cm.map_or(false, |c| c.dictionary_page_offset.is_some())),
        ("Bloom Filter", cm.map_or(false, |c| c.bloom_filter_offset.is_some())),
        ("Page Stats", cm.map_or(false, |c| c.encoding_stats.is_some())),
    ];
    let cols = Layout::horizontal([Constraint::Ratio(1, 4); 4]).split(chunks[1]);
    for (i, (t, ok)) in flags.iter().enumerate() {
        let col = if *ok { Color::Green } else { Color::Red };
        let b = Block::bordered()
            .style(Style::default().fg(col))
            .title(Span::styled(*t, Style::default().add_modifier(Modifier::BOLD)));
        let inner = b.inner(cols[i]);
        b.render(cols[i], buf);
        Paragraph::new(Span::styled(if *ok { "✓" } else { "✗" }, Style::default().fg(col).add_modifier(Modifier::BOLD)))
            .alignment(Alignment::Center)
            .style(Style::default().fg(Color::Reset))
            .render(inner, buf);
    }
    let lower = Layout::horizontal([Constraint::Percentage(38), Constraint::Percentage(62)]).split(chunks[2]);
    let left = Layout::vertical([Constraint::Length(7), Constraint::Length(6), Constraint::Min(0)]).split(lower[0]);
    let cm = match cm {
        Some(c) => c,
        None => return,
    };
    let ratio_v = ratio(cm.total_uncompressed_size, cm.total_compressed_size);
    let md_rows = vec![
        ("File Offset (B)", thousands(cc.map(|c| c.file_offset).unwrap_or(0))),
        ("Compressed Size", size_iec(cm.total_compressed_size as f64)),
        ("Uncompressed Size", size_iec(cm.total_uncompressed_size as f64)),
        ("Compression Ratio", format!("{:.2}x", ratio_v)),
        ("Compression Type", codec_name(cm.codec)),
    ];
    kv_table(
        "Metadata",
        Color::Blue,
        Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD),
        &md_rows,
        left[0],
        buf,
    );
    let (mn, mx, nc, dc) = match &cm.statistics {
        Some(s) => (
            s.min_bytes().map(|b| stat_value(cm.ptype, b)).unwrap_or_else(|| "N/A".into()),
            s.max_bytes().map(|b| stat_value(cm.ptype, b)).unwrap_or_else(|| "N/A".into()),
            s.null_count.map(|v| v.to_string()).unwrap_or_else(|| "N/A".into()),
            s.distinct_count.map(|v| v.to_string()).unwrap_or_else(|| "N/A".into()),
        ),
        None => ("N/A".into(), "N/A".into(), "N/A".into(), "N/A".into()),
    };
    let st_rows = vec![("Min", mn), ("Max", mx), ("Null Count", nc), ("Distinct Count", dc)];
    kv_table("Statistics", Color::Magenta, Style::default().add_modifier(Modifier::BOLD), &st_rows, left[1], buf);
    // pages
    let pages = list_pages(&m.file, cm);
    let pb = Block::bordered().border_style(Style::default().fg(Color::DarkGray)).title("Pages");
    let pin = pb.inner(lower[1]);
    pb.render(lower[1], buf);
    let hs = Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD);
    let header = Row::new(["#", "Page Type", "Size", "Rows", "Encoding"].iter().map(|h| Cell::from(*h).style(hs)));
    let rows: Vec<Row> = pages
        .iter()
        .enumerate()
        .map(|(i, p)| {
            Row::new(vec![
                Cell::from(Span::styled((i + 1).to_string(), Style::default().fg(Color::White))),
                Cell::from(Span::styled(page_type_name(p.page_type), Style::default().fg(Color::Cyan))),
                Cell::from(Span::styled(size_iec(p.compressed_size as f64), Style::default().fg(Color::White))),
                Cell::from(Span::styled(
                    p.num_values.map(|v| v.to_string()).unwrap_or_default(),
                    Style::default().fg(Color::White),
                )),
                Cell::from(Span::styled(
                    p.encoding.map(|e| title_case_encoding(&encoding_name(e))).unwrap_or_default(),
                    Style::default().fg(Color::Green),
                )),
            ])
        })
        .collect();
    let t = Table::new(
        rows,
        [
            Constraint::Length(3),
            Constraint::Percentage(25),
            Constraint::Percentage(25),
            Constraint::Percentage(17),
            Constraint::Percentage(25),
        ],
    )
    .header(header)
    .column_spacing(1)
    .flex(Flex::Legacy);
    Widget::render(t, pin, buf);
}

fn kv_table(title: &str, border: Color, label_style: Style, rows: &[(&str, String)], area: Rect, buf: &mut Buffer) {
    let b = Block::bordered().border_style(Style::default().fg(border)).title(title.to_string());
    let inner = b.inner(area);
    b.render(area, buf);
    let rs: Vec<Row> = rows
        .iter()
        .map(|(k, v)| {
            Row::new(vec![
                Cell::from(Span::styled(k.to_string(), label_style)),
                Cell::from(Span::styled(v.clone(), Style::default().fg(Color::White))),
            ])
        })
        .collect();
    let t = Table::new(rs, [Constraint::Length(18), Constraint::Fill(1)]).column_spacing(1);
    Widget::render(t, inner, buf);
}

