//! Application state, event loop and top-level drawing.
use crate::model::Model;
use crate::ui::{metadata, rowgroups, schema, tree, visualize};
use crossterm::event::{self, Event, KeyCode, KeyEventKind};
use ratatui::layout::{Constraint, Layout, Rect};
use ratatui::style::{Color, Modifier, Style};
use ratatui::text::{Line, Span};
use ratatui::widgets::{Block, BorderType, Paragraph, Tabs, Widget};
use ratatui::{DefaultTerminal, Frame};

pub struct App<'a> {
    pub model: &'a Model,
    pub tab: usize,
    pub vis: visualize::VisState,
    pub vis_cache: visualize::VisCache,
    pub schema: schema::SchemaState,
    pub rg: rowgroups::RgState,
    pub items: Vec<tree::TreeItem<'a>>,
    pub quit: bool,
}

const TABS: [&str; 4] = ["Visualize", "Metadata", "Schema", "Row Groups"];

impl<'a> App<'a> {
    pub fn new(model: &'a Model) -> Self {
        App {
            model,
            tab: 0,
            vis: visualize::VisState::default(),
            vis_cache: visualize::build_cache(model),
            schema: schema::SchemaState::default(),
            rg: rowgroups::RgState::default(),
            items: tree::build_items(&model.root),
            quit: false,
        }
    }

    pub fn run(&mut self, terminal: &mut DefaultTerminal) -> std::io::Result<()> {
        while !self.quit {
            terminal.draw(|f| self.draw(f))?;
            if let Event::Key(k) = event::read()? {
                if k.kind == KeyEventKind::Press {
                    self.on_key(k.code);
                }
            }
        }
        Ok(())
    }

    fn reset_tab_state(&mut self) {
        self.vis = visualize::VisState::default();
        self.schema = schema::SchemaState::default();
        self.rg = rowgroups::RgState::default();
    }

    fn on_key(&mut self, code: KeyCode) {
        match code {
            KeyCode::Char('q') | KeyCode::Char('Q') => {
                self.quit = true;
                return;
            }
            KeyCode::Tab => {
                self.tab = (self.tab + 1) % 4;
                self.reset_tab_state();
                return;
            }
            KeyCode::BackTab => {
                self.tab = (self.tab + 3) % 4;
                self.reset_tab_state();
                return;
            }
            _ => {}
        }
        match self.tab {
            0 => {
                let nrows = self.vis_cache.cells.len();
                let ncols = self.vis_cache.headers.len();
                visualize::key(&mut self.vis, code, nrows, ncols);
            }
            2 => schema::key(&mut self.schema, &self.items, code),
            3 => rowgroups::key(&mut self.rg, &self.items, self.model.meta.row_groups.len(), code),
            _ => {}
        }
    }

    fn draw(&mut self, f: &mut Frame) {
        let area = f.area();
        let [top, content, bottom] =
            Layout::vertical([Constraint::Length(3), Constraint::Min(0), Constraint::Length(1)]).areas(area);
        self.draw_top(f, top);
        self.draw_bottom(f, bottom);
        let buf = f.buffer_mut();
        match self.tab {
            0 => visualize::render(self.model, &self.vis_cache, &mut self.vis, content, buf),
            1 => metadata::render(self.model, content, buf),
            2 => schema::render(self.model, &self.items, &mut self.schema, content, buf),
            _ => rowgroups::render(self.model, &self.items, &mut self.rg, content, buf),
        }
    }

    fn draw_top(&self, f: &mut Frame, area: Rect) {
        let block = Block::bordered().border_type(BorderType::Rounded).border_style(Style::default().fg(Color::LightYellow));
        let inner = block.inner(area);
        f.render_widget(block, area);
        let path_w = unicode_width(&self.model.path) as u16;
        let [tabs_area, path_area] = Layout::horizontal([Constraint::Min(0), Constraint::Length(path_w)]).areas(inner);
        let tabs = Tabs::new(TABS.to_vec())
            .select(self.tab)
            .highlight_style(Style::default().add_modifier(Modifier::REVERSED))
            .divider(" ");
        f.render_widget(tabs, tabs_area);
        f.render_widget(
            Paragraph::new(self.model.path.clone()).style(Style::default().fg(Color::Green)).right_aligned(),
            path_area,
        );
    }

    fn draw_bottom(&self, f: &mut Frame, area: Rect) {
        let [left, right] = Layout::horizontal([Constraint::Length(7), Constraint::Min(0)]).areas(area);
        f.render_widget(
            Paragraph::new(Span::styled("parqeye", Style::default().fg(Color::Green).add_modifier(Modifier::BOLD))),
            left,
        );
        let g = Style::default().fg(Color::Green);
        let w = Style::default().fg(Color::White);
        let b = Style::default().fg(Color::Blue);
        let mut spans: Vec<Span> = Vec::new();
        match self.tab {
            0 => {
                spans.extend([
                    Span::styled("↑", g),
                    Span::styled("/", w),
                    Span::styled("↓", b),
                    Span::raw(" : Row"),
                    Span::styled(" | ", w),
                    Span::styled("→", g),
                    Span::styled("/", w),
                    Span::styled("←", b),
                    Span::raw(" : Column"),
                    Span::styled(" | ", w),
                    Span::styled("u", g),
                    Span::styled("/", w),
                    Span::styled("d", b),
                    Span::raw(" : Page - "),
                ]);
            }
            2 => {
                spans.extend([
                    Span::styled("←", g),
                    Span::styled("/", w),
                    Span::styled("→", b),
                    Span::raw(" : Scroll, "),
                    Span::styled("↑", g),
                    Span::styled("/", w),
                    Span::styled("↓", b),
                    Span::raw(" : Schema - "),
                ]);
            }
            3 => {
                spans.extend([
                    Span::styled("→", g),
                    Span::styled("/", w),
                    Span::styled("←", b),
                    Span::raw(" : Iterate Row Groups, "),
                    Span::styled("↑", g),
                    Span::styled("/", w),
                    Span::styled("↓", b),
                    Span::raw(" : Schema - "),
                ]);
            }
            _ => {}
        }
        spans.extend([
            Span::styled("[Tab]", g),
            Span::raw(" Next Tab, "),
            Span::styled("[Q]", b),
            Span::raw("uit"),
        ]);
        f.render_widget(Paragraph::new(Line::from(spans)).right_aligned(), right);
    }
}

fn unicode_width(s: &str) -> usize {
    Line::from(s).width()
}

