//! Chart rendering helper reproducing truncating point placement.
use ratatui::buffer::Buffer;
use ratatui::layout::{Constraint, Flex, Layout, Rect};
use ratatui::style::{Color, Style};
use ratatui::text::Line;
use ratatui::widgets::{Axis, Block, Chart, Dataset, Widget};

pub struct Series<'a> {
    pub name: Option<&'a str>,
    pub color: Color,
    pub points: Vec<(f64, f64)>,
}

fn graph_area(area: Rect, ylabels: &[String], xlabels: &[String]) -> Option<Rect> {
    if area.height == 0 || area.width == 0 {
        return None;
    }
    let mut x = area.left();
    let mut y = area.bottom() - 1;
    if !xlabels.is_empty() && y > area.top() {
        y -= 1;
    }
    let has_y = !ylabels.is_empty();
    let mut mw = ylabels.iter().map(|l| Line::from(l.as_str()).width()).max().unwrap_or(0) as u16;
    if let Some(f) = xlabels.first() {
        let fw = Line::from(f.as_str()).width() as u16;
        mw = mw.max(fw.saturating_sub(u16::from(has_y)));
    }
    x += mw.min(area.width / 3);
    if !xlabels.is_empty() && y > area.top() {
        y -= 1;
    }
    if has_y && x + 1 < area.right() {
        x += 1;
    }
    let gw = area.right().saturating_sub(x);
    let gh = y.saturating_sub(area.top()).saturating_add(1);
    Some(Rect::new(x, area.top(), gw, gh))
}

#[allow(clippy::too_many_arguments)]
pub fn render_chart(
    area: Rect,
    block: Block,
    xb: [f64; 2],
    yb: [f64; 2],
    xlabels: Vec<String>,
    ylabels: Vec<String>,
    axis_style: Style,
    series: &[Series],
    buf: &mut Buffer,
) {
    let inner = block.inner(area);
    let empty: Vec<(f64, f64)> = vec![];
    let ds: Vec<Dataset> = vec![Dataset::default().data(&empty)];
    let chart = Chart::new(ds)
        .block(block)
        .x_axis(Axis::default().bounds(xb).labels(xlabels.clone()).style(axis_style))
        .y_axis(Axis::default().bounds(yb).labels(ylabels.clone()).style(axis_style));
    chart.render(area, buf);
    let g = match graph_area(inner, &ylabels, &xlabels) {
        Some(g) => g,
        None => return,
    };
    if g.width == 0 || g.height == 0 {
        return;
    }
    let (left, right) = (xb[0], xb[1]);
    let (bottom, top) = (yb[0], yb[1]);
    let w = right - left;
    let h = top - bottom;
    if w > 0.0 && h > 0.0 {
        for s in series {
            for &(px, py) in &s.points {
                if px < left || px > right || py < bottom || py > top {
                    continue;
                }
                let cx = ((px - left) * (g.width as f64 - 1.0) / w) as usize;
                let cy = ((top - py) * (g.height as f64 - 1.0) / h) as usize;
                if cx < g.width as usize && cy < g.height as usize {
                    let cell = &mut buf[(g.x + cx as u16, g.y + cy as u16)];
                    cell.set_symbol("•").set_fg(s.color);
                }
            }
        }
    }
    // legend
    let names: Vec<(&str, Color)> = series.iter().filter_map(|s| s.name.map(|n| (n, s.color))).collect();
    if let Some(inner_w) = names.iter().map(|(n, _)| Line::from(*n).width() as u16).max() {
        let lw = inner_w + 2;
        let lh = names.len() as u16 + 2;
        let [mw] = Layout::horizontal([Constraint::Ratio(1, 4)]).flex(Flex::Start).areas(g);
        let [mh] = Layout::vertical([Constraint::Ratio(1, 4)]).flex(Flex::Start).areas(g);
        if inner_w > 0 && lw <= mw.width && lh <= mh.height {
            let la = Rect::new(g.right() - lw, g.top(), lw, lh);
            let original_style = buf[(area.left(), area.top())].style();
            buf.set_style(la, original_style);
            Block::bordered().render(la, buf);
            for (i, (n, c)) in names.iter().enumerate() {
                Line::from(*n).style(Style::default().fg(*c)).render(
                    Rect { x: la.x + 1, y: la.y + 1 + i as u16, width: la.width - 2, height: 1 },
                    buf,
                );
            }
        }
    }
}
