//! Block rendering with title placement matching the original behaviour.
use ratatui::buffer::Buffer;
use ratatui::layout::Rect;
use ratatui::text::Line;
use ratatui::widgets::{Block, Borders, Widget};

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Al {
    Left,
    Center,
}

pub struct Titles<'a> {
    pub top: Option<(Line<'a>, Al)>,
    pub bottom: Option<(Line<'a>, Al)>,
}

impl<'a> Titles<'a> {
    pub fn none() -> Self {
        Titles { top: None, bottom: None }
    }
    pub fn top(l: Line<'a>, a: Al) -> Self {
        Titles { top: Some((l, a)), bottom: None }
    }
    pub fn with_bottom(mut self, l: Line<'a>, a: Al) -> Self {
        self.bottom = Some((l, a));
        self
    }
}

/// Render `block` (which must not carry titles) together with `titles`.
/// Returns the inner area (accounting for title rows like ratatui does).
pub fn render_block(block: Block, borders: Borders, titles: Titles, area: Rect, buf: &mut Buffer) -> Rect {
    let mut probe = block.clone();
    if let Some((l, _)) = &titles.top {
        probe = probe.title_top(l.clone());
    }
    if let Some((l, _)) = &titles.bottom {
        probe = probe.title_bottom(l.clone());
    }
    let inner = probe.inner(area);
    block.render(area, buf);
    let area = area.intersection(buf.area);
    if area.is_empty() {
        return inner;
    }
    let lb = u16::from(borders.contains(Borders::LEFT));
    let rb = u16::from(borders.contains(Borders::RIGHT));
    let ta_x = area.left().saturating_add(lb);
    let ta_w = area.width.saturating_sub(lb).saturating_sub(rb);
    for (t, top) in [(titles.top, true), (titles.bottom, false)] {
        if let Some((line, al)) = t {
            let y = if top { area.top() } else { area.bottom().saturating_sub(1) };
            let ta = Rect { x: ta_x, y, width: ta_w, height: 1 };
            if ta.is_empty() {
                continue;
            }
            let w = line.width() as u16;
            match al {
                Al::Left => {
                    let r = Rect { width: w.min(ta.width), ..ta };
                    line.left_aligned().render(r, buf);
                }
                Al::Center => {
                    if w <= ta.width {
                        let x = ta.x + (ta.width - w) / 2;
                        line.left_aligned().render(Rect { x, width: w, ..ta }, buf);
                    } else {
                        line.centered().render(ta, buf);
                    }
                }
            }
        }
    }
    inner
}
