cd /workspace && grep -n "unicode" Cargo.toml; cat >> src/ui/util.rs <<'EOF'

/// Write a string like `Buffer::set_stringn` did in older ratatui versions:
/// control characters are kept (with a width of one cell).
pub fn set_str_raw(
    buf: &mut ratatui::buffer::Buffer,
    mut x: u16,
    y: u16,
    s: &str,
    max_width: usize,
    style: ratatui::style::Style,
) -> u16 {
    use unicode_segmentation::UnicodeSegmentation;
    use unicode_width::UnicodeWidthStr;
    let a = buf.area;
    if y < a.top() || y >= a.bottom() || x >= a.right() {
        return x;
    }
    let max_width = u16::try_from(max_width).unwrap_or(u16::MAX);
    let mut remaining = a.right().saturating_sub(x).min(max_width);
    for g in s.graphemes(true) {
        let w = g.width() as u16;
        if w == 0 {
            continue;
        }
        if remaining < w {
            break;
        }
        remaining -= w;
        buf[(x, y)].set_symbol(g).set_style(style);
        let next = x + w;
        x += 1;
        while x < next {
            buf[(x, y)].reset();
            x += 1;
        }
    }
    x
}

pub fn has_control(s: &str) -> bool {
    s.chars().any(|c| c.is_control())
}
